// Tool translations: desc and rgpd_note per language per tool slug.
// Falls back to Portuguese source if a language/slug is absent.

export type ToolTranslation = { desc: string; rgpd_note?: string };
export const toolTranslations: Partial<Record<string, Record<string, ToolTranslation>>> = {

  en: {
    'chatgpt': { desc: "General-purpose language model. Useful for adapting texts, generating differentiated exercises, creating contextualised examples, and drafting support materials.", rgpd_note: "Free version (ChatGPT.com) may use conversations to train the model. Disable in Settings > Data Controls. Never submit student names, diagnoses, or identifying data. For institutional use, consider the Teams or Enterprise plan with a Data Processing Agreement." },
    'deepl': { desc: "High-quality automatic translation with superior performance for European languages. More contextually accurate than Google Translate for academic texts.", rgpd_note: "Free version sends text to external servers (DeepL GmbH, Germany, within the EU). Pro version includes a GDPR-compliant data processing contract. Never translate documents containing full names or sensitive student data." },
    'diffit': { desc: "Generates differentiated reading materials from any text, URL, or topic. Automatically adjusts linguistic complexity while maintaining academic content. Useful for creating versions of the same text for different student profiles.", rgpd_note: "Diffit (USA): submitted content may be processed by external AI models. Do not enter personal student data; use only with anonymous curricular content." },
    'elsa-speak': { desc: "AI-powered English pronunciation trainer. Analyses the user's speech and provides phoneme-by-phoneme feedback. Particularly useful for EAL learners and for teachers identifying pronunciation patterns linked to a student's first language.", rgpd_note: "ELSA Corp. (USA): voice recordings processed on their servers. Free version has limited features; Pro is paid. For minors, check the privacy policy and obtain parental consent before using voice data." },
    'grammarly': { desc: "AI writing assistant that corrects grammar, spelling, and punctuation, and suggests improvements to clarity and tone. Available as a browser extension and integrated into Google Docs and Word.", rgpd_note: "Grammarly Inc. (USA): data sent to US servers. Free version may use text to improve the model. For sensitive student content, do not use texts with identifying data. Business version includes additional privacy controls." },
    'immersive-reader': { desc: "Free immersive reader integrated into Word, Teams, OneNote, and Edge. Splits syllables, highlights parts of speech, reads text aloud, and adjusts spacing and font size. Works directly in class documents.", rgpd_note: "Integrated into Microsoft products: data processing follows Microsoft 365 privacy policy. In school environments with Microsoft 365 Education licence, student data is treated as school data and not used for advertising." },
    'khanmigo': { desc: "Free learning platform with AI tutor (Khanmigo). The AI tutor adapts explanations to each student's pace, asks Socratic questions rather than giving direct answers, and tracks progress. Particularly useful for gifted students who advance beyond the curriculum, and for EAL learners with content available in multiple languages.", rgpd_note: "Khan Academy (USA, non-profit): student data for minors requires an account created by a teacher or guardian. Khan Academy does not sell data for advertising. Khanmigo has an additional cost for teachers; the base platform is free. COPPA-compliant for US users; verify GDPR suitability for EU use." },
    'magicschool': { desc: "AI platform designed specifically for teachers. Includes tools to differentiate lesson plans, create accommodations for students with SEN, generate communications for parents and guardians, and adapt materials to different reading levels.", rgpd_note: "MagicSchool AI (USA): platform designed for educational contexts, COPPA/FERPA compliant for US schools. For EU use, verify GDPR compliance before entering student data. Use only with anonymous or fictional data until a DPA is confirmed with the school." },
    'natural-reader': { desc: "Converts written text to synthesised speech. Useful for students with dyslexia or dyspraxia who benefit from audio support while reading.", rgpd_note: "Free version is web-based. Do not submit texts with personally identifiable student data." },
    'notebooklm': { desc: "Google tool that ingests documents and allows users to ask questions, generate summaries, and create study guides from the uploaded material. Useful for adapting long texts.", rgpd_note: "Google product. Data processed under Google Workspace terms. Do not upload documents containing personal student data. Use with anonymous curricular materials only." },
    'otter': { desc: "Real-time automatic audio transcription. Useful for students with ADHD or auditory processing difficulties to follow spoken explanations, and for teachers creating lesson transcripts students can review.", rgpd_note: "Otter.ai (USA): audio recordings and transcripts stored on their servers. Obtain informed consent before recording any lesson. Free version stores recordings indefinitely; confirm the retention policy. Do not use to record conversations with minors without explicit authorisation." },
    'quizlet': { desc: "Flashcard and learning game platform. The AI feature automatically generates study sets from notes or documents. Effective for consolidating vocabulary and concepts, especially for profiles with limited working memory.", rgpd_note: "Quizlet Inc. (USA): usage data shared with third parties for advertising in the free version. For students under 13, an account created by a teacher is required (Quizlet Teacher). Plus or School version removes adverts and strengthens privacy." },
    'speechify': { desc: "High-quality text-to-speech converter with natural voices in multiple languages. Reads PDFs, web pages, documents, and emails. Allows reading speed adjustment and highlights text as it is read. Useful for students with dyslexia or dyspraxia.", rgpd_note: "Speechify Inc. (USA): submitted content processed on their servers. Free version has a listening-minute limit; Premium is paid. For documents containing student data, use only anonymous curricular texts." },
  },

  es: {
    'chatgpt': { desc: "Modelo de lenguaje de uso general. Útil para adaptar textos, generar ejercicios diferenciados, crear ejemplos contextualizados y redactar materiales de apoyo.", rgpd_note: "La versión gratuita puede usar conversaciones para entrenar el modelo. Desactivar en Ajustes > Controles de datos. No enviar nunca nombres, diagnósticos ni datos identificables de alumnos. Para uso institucional, considerar el plan Teams o Enterprise con DPA." },
    'deepl': { desc: "Traducción automática de alta calidad, con rendimiento superior en lenguas europeas. Más preciso contextualmente que Google Translate para textos académicos.", rgpd_note: "La versión gratuita envía texto a servidores externos (DeepL GmbH, Alemania, dentro de la UE). La versión Pro incluye contrato de tratamiento de datos compatible con el RGPD. No traducir documentos con nombres completos o datos sensibles de alumnos." },
    'diffit': { desc: "Genera materiales de lectura diferenciados a partir de cualquier texto, URL o tema. Adapta automáticamente el nivel de complejidad lingüística manteniendo el contenido académico. Útil para crear versiones de un mismo texto para distintos perfiles de alumnos.", rgpd_note: "Diffit (EE.UU.): el contenido enviado puede ser procesado por modelos de IA externos. No introducir datos personales de alumnos; usar solo con contenido curricular anónimo." },
    'elsa-speak': { desc: "Entrenador de pronunciación en inglés con IA. Analiza el habla del usuario y proporciona retroalimentación fonema a fonema. Especialmente útil para aprendices de inglés como L2 y para docentes que identifican patrones de pronunciación vinculados a la lengua materna del alumno.", rgpd_note: "ELSA Corp. (EE.UU.): grabaciones de voz procesadas en sus servidores. La versión gratuita tiene funcionalidades limitadas; la Pro es de pago. Para menores, revisar la política de privacidad y obtener consentimiento parental antes de utilizar datos de voz." },
    'grammarly': { desc: "Asistente de escritura con IA que corrige gramática, ortografía y puntuación, y sugiere mejoras de claridad y tono. Disponible como extensión de navegador e integrado en Google Docs y Word.", rgpd_note: "Grammarly Inc. (EE.UU.): datos enviados a servidores estadounidenses. La versión gratuita puede usar textos para mejorar el modelo. Para contenido sensible de alumnos, no usar textos con datos identificables. La versión Business incluye controles de privacidad adicionales." },
    'immersive-reader': { desc: "Lector inmersivo gratuito integrado en Word, Teams, OneNote y Edge. Separa sílabas, resalta categorías gramaticales, lee el texto en voz alta y ajusta el espaciado y el tamaño de fuente. Funciona directamente en los documentos de clase.", rgpd_note: "Integrado en los productos Microsoft: el tratamiento de datos sigue la política de privacidad de Microsoft 365. En entornos escolares con licencia Microsoft 365 Education, los datos de los alumnos se tratan como datos escolares y no se usan para publicidad." },
    'khanmigo': { desc: "Plataforma de aprendizaje gratuita con tutor de IA (Khanmigo). El tutor adapta las explicaciones al ritmo del alumno, formula preguntas socráticas en lugar de dar respuestas directas y realiza un seguimiento del progreso. Especialmente útil para alumnos con altas capacidades y para aprendices de español como L2 con contenido en múltiples idiomas.", rgpd_note: "Khan Academy (EE.UU., organización sin ánimo de lucro): los datos de alumnos menores requieren una cuenta creada por docente o tutor legal. Khan Academy no vende datos con fines publicitarios. Khanmigo tiene un coste adicional para docentes; la plataforma base es gratuita. Verificar adecuación al RGPD para uso en la UE." },
    'magicschool': { desc: "Plataforma de IA diseñada específicamente para docentes. Incluye herramientas para diferenciar unidades didácticas, crear adaptaciones para alumnos con NEE, generar comunicaciones para familias y adaptar materiales a distintos niveles de lectura.", rgpd_note: "MagicSchool AI (EE.UU.): plataforma diseñada para el contexto educativo, con conformidad COPPA/FERPA para escuelas estadounidenses. Para uso en la UE, verificar la adecuación al RGPD antes de introducir datos de alumnos. Usar solo con datos anónimos o ficticios hasta confirmar el DPA con el centro." },
    'natural-reader': { desc: "Convierte texto escrito en voz sintetizada. Útil para alumnos con dislexia o dispraxia que se benefician del apoyo auditivo durante la lectura.", rgpd_note: "La versión gratuita es en línea. No enviar textos con datos personales identificables de alumnos." },
    'notebooklm': { desc: "Herramienta de Google que procesa documentos y permite hacer preguntas, generar resúmenes y crear guías de estudio a partir del material cargado. Útil para adaptar textos largos.", rgpd_note: "Producto de Google. Datos procesados según los términos de Google Workspace. No cargar documentos con datos personales de alumnos. Usar únicamente con materiales curriculares anónimos." },
    'otter': { desc: "Transcripción automática de audio en tiempo real. Útil para alumnos con TDAH o dificultades de procesamiento auditivo para seguir explicaciones orales, y para docentes que crean transcripciones de clase revisables.", rgpd_note: "Otter.ai (EE.UU.): grabaciones de audio y transcripciones almacenadas en sus servidores. Obtener consentimiento informado antes de grabar cualquier clase. La versión gratuita almacena grabaciones indefinidamente; confirmar la política de retención. No usar para grabar conversaciones con menores sin autorización explícita." },
    'quizlet': { desc: "Plataforma de tarjetas de estudio y juegos de aprendizaje. La función de IA genera conjuntos de estudio automáticamente a partir de notas o documentos. Eficaz para consolidar vocabulario y conceptos, especialmente para perfiles con memoria de trabajo limitada.", rgpd_note: "Quizlet Inc. (EE.UU.): datos de uso compartidos con terceros para publicidad en la versión gratuita. Para alumnos menores de 13 años, se requiere una cuenta creada por el docente (Quizlet Teacher). La versión Plus o School elimina los anuncios y refuerza la privacidad." },
    'speechify': { desc: "Conversor de texto a voz de alta calidad con voces naturales en múltiples idiomas. Lee PDFs, páginas web, documentos y correos electrónicos. Permite ajustar la velocidad de lectura y resalta el texto a medida que se lee. Útil para alumnos con dislexia o dispraxia.", rgpd_note: "Speechify Inc. (EE.UU.): contenido enviado procesado en sus servidores. La versión gratuita tiene un límite de minutos de escucha; Premium es de pago. Para documentos con datos de alumnos, usar únicamente textos curriculares anónimos." },
  },

  fr: {
    'chatgpt': { desc: "Modèle de langage à usage général. Utile pour adapter des textes, générer des exercices différenciés, créer des exemples contextualisés et rédiger des supports pédagogiques.", rgpd_note: "La version gratuite peut utiliser les conversations pour entraîner le modèle. Désactiver dans Paramètres > Contrôles des données. Ne jamais soumettre les noms, diagnostics ou données identifiables des élèves. Pour un usage institutionnel, envisager le plan Teams ou Enterprise avec un accord de traitement des données." },
    'deepl': { desc: "Traduction automatique de haute qualité, avec des performances supérieures pour les langues européennes. Plus précis contextuellement que Google Traduction pour les textes académiques.", rgpd_note: "La version gratuite envoie le texte à des serveurs externes (DeepL GmbH, Allemagne, dans l'UE). La version Pro inclut un contrat de traitement des données conforme au RGPD. Ne jamais traduire des documents contenant les noms complets ou des données sensibles des élèves." },
    'diffit': { desc: "Génère des supports de lecture différenciés à partir de n'importe quel texte, URL ou sujet. Adapte automatiquement le niveau de complexité linguistique tout en maintenant le contenu académique. Utile pour créer des versions d'un même texte pour différents profils d'élèves.", rgpd_note: "Diffit (États-Unis) : le contenu soumis peut être traité par des modèles d'IA externes. Ne pas saisir de données personnelles sur les élèves ; utiliser uniquement avec un contenu curriculaire anonyme." },
    'elsa-speak': { desc: "Entraîneur de prononciation en anglais par IA. Analyse la parole de l'utilisateur et fournit un retour phonème par phonème. Particulièrement utile pour les apprenants d'anglais langue étrangère et pour les enseignants qui identifient des schémas de prononciation liés à la langue maternelle de l'élève.", rgpd_note: "ELSA Corp. (États-Unis) : enregistrements vocaux traités sur leurs serveurs. La version gratuite a des fonctionnalités limitées ; la version Pro est payante. Pour les mineurs, vérifier la politique de confidentialité et obtenir le consentement parental avant d'utiliser des données vocales." },
    'grammarly': { desc: "Assistant d'écriture par IA qui corrige la grammaire, l'orthographe et la ponctuation, et suggère des améliorations de clarté et de ton. Disponible comme extension de navigateur et intégré dans Google Docs et Word.", rgpd_note: "Grammarly Inc. (États-Unis) : données envoyées vers des serveurs américains. La version gratuite peut utiliser les textes pour améliorer le modèle. Pour le contenu sensible des élèves, ne pas utiliser de textes avec des données identifiables. La version Business inclut des contrôles de confidentialité supplémentaires." },
    'immersive-reader': { desc: "Lecteur immersif gratuit intégré dans Word, Teams, OneNote et Edge. Sépare les syllabes, surligne les classes grammaticales, lit le texte à voix haute et ajuste l'espacement et la taille de police. Fonctionne directement dans les documents de classe.", rgpd_note: "Intégré aux produits Microsoft : le traitement des données suit la politique de confidentialité de Microsoft 365. Dans un environnement scolaire avec licence Microsoft 365 Éducation, les données des élèves sont traitées comme des données scolaires et ne sont pas utilisées à des fins publicitaires." },
    'khanmigo': { desc: "Plateforme d'apprentissage gratuite avec tuteur IA (Khanmigo). Le tuteur adapte les explications au rythme de l'élève, pose des questions socratiques plutôt que de donner des réponses directes, et suit les progrès. Particulièrement utile pour les élèves à haut potentiel et pour les élèves allophones avec du contenu en plusieurs langues.", rgpd_note: "Khan Academy (États-Unis, association à but non lucratif) : les données des élèves mineurs nécessitent un compte créé par un enseignant ou un responsable légal. Khan Academy ne revend pas de données à des fins publicitaires. Khanmigo a un coût supplémentaire pour les enseignants ; la plateforme de base est gratuite. Vérifier la conformité au RGPD pour un usage dans l'UE." },
    'magicschool': { desc: "Plateforme d'IA conçue spécifiquement pour les enseignants. Comprend des outils pour différencier les séquences pédagogiques, créer des aménagements pour les élèves à besoins éducatifs particuliers, générer des communications pour les familles et adapter les supports à différents niveaux de lecture.", rgpd_note: "MagicSchool AI (États-Unis) : plateforme conçue pour le contexte éducatif, conformité COPPA/FERPA pour les écoles américaines. Pour un usage dans l'UE, vérifier la conformité au RGPD avant de saisir des données d'élèves. N'utiliser qu'avec des données anonymes ou fictives jusqu'à confirmation d'un accord de traitement des données avec l'établissement." },
    'natural-reader': { desc: "Convertit du texte écrit en voix de synthèse. Utile pour les élèves dyslexiques ou dyspraxiques qui bénéficient d'un accompagnement auditif pendant la lecture.", rgpd_note: "La version gratuite est en ligne. Ne pas soumettre de textes contenant des données personnelles identifiables des élèves." },
    'notebooklm': { desc: "Outil Google qui ingère des documents et permet de poser des questions, de générer des résumés et de créer des guides d'étude à partir du matériel chargé. Utile pour adapter des textes longs.", rgpd_note: "Produit Google. Données traitées selon les conditions Google Workspace. Ne pas charger de documents contenant des données personnelles d'élèves. Utiliser uniquement avec des matériaux curriculaires anonymes." },
    'otter': { desc: "Transcription automatique audio en temps réel. Utile pour les élèves ayant un TDAH ou des difficultés de traitement auditif pour suivre les explications orales, et pour les enseignants qui créent des transcriptions de cours révisables.", rgpd_note: "Otter.ai (États-Unis) : enregistrements audio et transcriptions stockés sur leurs serveurs. Obtenir le consentement éclairé avant d'enregistrer tout cours. La version gratuite conserve les enregistrements indéfiniment ; confirmer la politique de conservation. Ne pas enregistrer de conversations avec des mineurs sans autorisation explicite." },
    'quizlet': { desc: "Plateforme de fiches mémo et de jeux d'apprentissage. La fonction IA génère automatiquement des séries d'étude à partir de notes ou de documents. Efficace pour consolider le vocabulaire et les concepts, en particulier pour les profils ayant une mémoire de travail limitée.", rgpd_note: "Quizlet Inc. (États-Unis) : données d'utilisation partagées avec des tiers à des fins publicitaires dans la version gratuite. Pour les élèves de moins de 13 ans, un compte créé par l'enseignant est requis (Quizlet Teacher). La version Plus ou School supprime les publicités et renforce la confidentialité." },
    'speechify': { desc: "Convertisseur texte-parole de haute qualité avec des voix naturelles dans plusieurs langues. Lit des PDF, des pages web, des documents et des e-mails. Permet d'ajuster la vitesse de lecture et surligne le texte au fil de la lecture. Utile pour les élèves dyslexiques ou dyspraxiques.", rgpd_note: "Speechify Inc. (États-Unis) : contenu soumis traité sur leurs serveurs. La version gratuite a une limite de minutes d'écoute ; Premium est payant. Pour les documents contenant des données d'élèves, n'utiliser que des textes curriculaires anonymes." },
  },

  it: {
    'chatgpt': { desc: "Modello linguistico di uso generale. Utile per adattare testi, generare esercizi differenziati, creare esempi contestualizzati e redigere materiali di supporto.", rgpd_note: "La versione gratuita può usare le conversazioni per addestrare il modello. Disattivare in Impostazioni > Controlli sui dati. Non inviare mai nomi, diagnosi o dati identificativi degli alunni. Per uso istituzionale, considerare il piano Teams o Enterprise con un accordo sul trattamento dei dati." },
    'deepl': { desc: "Traduzione automatica di alta qualità, con prestazioni superiori per le lingue europee. Più preciso contestualmente di Google Translate per i testi accademici.", rgpd_note: "La versione gratuita invia testo a server esterni (DeepL GmbH, Germania, all'interno dell'UE). La versione Pro include un contratto di trattamento dei dati conforme al GDPR. Non tradurre mai documenti contenenti nomi completi o dati sensibili degli alunni." },
    'diffit': { desc: "Genera materiali di lettura differenziati da qualsiasi testo, URL o argomento. Adatta automaticamente il livello di complessità linguistica mantenendo il contenuto accademico. Utile per creare versioni dello stesso testo per diversi profili di alunni.", rgpd_note: "Diffit (USA): il contenuto inviato può essere elaborato da modelli IA esterni. Non inserire dati personali degli alunni; usare solo con contenuto curriculare anonimo." },
    'elsa-speak': { desc: "Trainer di pronuncia dell'inglese con IA. Analizza il parlato dell'utente e fornisce feedback fonema per fonema. Particolarmente utile per gli apprendenti di inglese come L2 e per gli insegnanti che identificano schemi di pronuncia legati alla lingua madre dell'alunno.", rgpd_note: "ELSA Corp. (USA): registrazioni vocali elaborate sui loro server. La versione gratuita ha funzionalità limitate; la Pro è a pagamento. Per i minori, verificare l'informativa sulla privacy e ottenere il consenso dei genitori prima di utilizzare dati vocali." },
    'grammarly': { desc: "Assistente di scrittura con IA che corregge grammatica, ortografia e punteggiatura, e suggerisce miglioramenti di chiarezza e tono. Disponibile come estensione del browser e integrato in Google Docs e Word.", rgpd_note: "Grammarly Inc. (USA): dati inviati a server statunitensi. La versione gratuita può usare i testi per migliorare il modello. Per i contenuti sensibili degli alunni, non usare testi con dati identificativi. La versione Business include controlli sulla privacy aggiuntivi." },
    'immersive-reader': { desc: "Lettore immersivo gratuito integrato in Word, Teams, OneNote ed Edge. Separa le sillabe, evidenzia le parti del discorso, legge il testo ad alta voce e regola la spaziatura e la dimensione del carattere. Funziona direttamente nei documenti di classe.", rgpd_note: "Integrato nei prodotti Microsoft: il trattamento dei dati segue l'informativa sulla privacy di Microsoft 365. In ambienti scolastici con licenza Microsoft 365 Education, i dati degli alunni vengono trattati come dati scolastici e non sono utilizzati per la pubblicità." },
    'khanmigo': { desc: "Piattaforma di apprendimento gratuita con tutor IA (Khanmigo). Il tutor adatta le spiegazioni al ritmo dell'alunno, pone domande socratiche invece di fornire risposte dirette e monitora i progressi. Particolarmente utile per gli alunni plusdotati e per chi impara l'italiano come L2.", rgpd_note: "Khan Academy (USA, organizzazione senza scopo di lucro): i dati degli alunni minori richiedono un account creato da un insegnante o un tutore legale. Khan Academy non vende dati per la pubblicità. Khanmigo ha un costo aggiuntivo per gli insegnanti; la piattaforma base è gratuita. Verificare l'adeguatezza al GDPR per l'uso nell'UE." },
    'magicschool': { desc: "Piattaforma IA progettata specificamente per gli insegnanti. Include strumenti per differenziare le unità didattiche, creare accomodamenti per gli alunni con BES, generare comunicazioni per le famiglie e adattare i materiali a diversi livelli di lettura.", rgpd_note: "MagicSchool AI (USA): piattaforma progettata per il contesto educativo, conforme a COPPA/FERPA per le scuole americane. Per l'uso nell'UE, verificare la conformità al GDPR prima di inserire dati degli alunni. Usare solo con dati anonimi o fittizi fino alla conferma di un accordo di trattamento dei dati con la scuola." },
    'natural-reader': { desc: "Converte testo scritto in voce sintetizzata. Utile per gli alunni con dislessia o disprassia che beneficiano di un supporto uditivo durante la lettura.", rgpd_note: "La versione gratuita è basata sul web. Non inviare testi con dati personali identificativi degli alunni." },
    'notebooklm': { desc: "Strumento Google che elabora documenti e consente di fare domande, generare riepiloghi e creare guide di studio dal materiale caricato. Utile per adattare testi lunghi.", rgpd_note: "Prodotto Google. Dati elaborati secondo i termini di Google Workspace. Non caricare documenti con dati personali degli alunni. Usare solo con materiali curriculari anonimi." },
    'otter': { desc: "Trascrizione automatica audio in tempo reale. Utile per gli alunni con ADHD o difficoltà di elaborazione uditiva per seguire le spiegazioni orali, e per gli insegnanti che creano trascrizioni delle lezioni da rivedere.", rgpd_note: "Otter.ai (USA): registrazioni audio e trascrizioni archiviate sui loro server. Ottenere il consenso informato prima di registrare qualsiasi lezione. La versione gratuita conserva le registrazioni a tempo indeterminato; verificare la politica di conservazione. Non registrare conversazioni con minori senza autorizzazione esplicita." },
    'quizlet': { desc: "Piattaforma di flashcard e giochi di apprendimento. La funzione IA genera automaticamente set di studio da note o documenti. Efficace per consolidare il vocabolario e i concetti, specialmente per i profili con memoria di lavoro limitata.", rgpd_note: "Quizlet Inc. (USA): dati di utilizzo condivisi con terze parti per scopi pubblicitari nella versione gratuita. Per gli alunni sotto i 13 anni è necessario un account creato dall'insegnante (Quizlet Teacher). La versione Plus o School rimuove gli annunci e rafforza la privacy." },
    'speechify': { desc: "Convertitore testo-voce di alta qualità con voci naturali in più lingue. Legge PDF, pagine web, documenti ed e-mail. Permette di regolare la velocità di lettura ed evidenzia il testo man mano che viene letto. Utile per gli alunni con dislessia o disprassia.", rgpd_note: "Speechify Inc. (USA): contenuto inviato elaborato sui loro server. La versione gratuita ha un limite di minuti di ascolto; Premium è a pagamento. Per i documenti con dati degli alunni, usare solo testi curriculari anonimi." },
  },

  hr: {
    'chatgpt': { desc: "Jezični model opće namjene. Koristan za prilagodbu tekstova, generiranje diferenciranih vježbi, stvaranje kontekstualiziranih primjera i izradu materijala za podršku.", rgpd_note: "Besplatna verzija može koristiti razgovore za treniranje modela. Isključiti u Postavkama > Kontrola podataka. Nikada ne slati imena, dijagnoze ni identificirajuće podatke učenika. Za institucionalnu upotrebu razmotriti plan Teams ili Enterprise s ugovorom o obradi podataka." },
    'deepl': { desc: "Visokokvalitetni automatski prijevod s odličnim rezultatima za europske jezike. Kontekstualno precizniji od Google Prevoditelja za akademske tekstove.", rgpd_note: "Besplatna verzija šalje tekst na vanjske poslužitelje (DeepL GmbH, Njemačka, unutar EU). Pro verzija uključuje ugovor o obradi podataka u skladu s GDPR-om. Nikada ne prevoditi dokumente s punim imenima ili osjetljivim podacima učenika." },
    'diffit': { desc: "Generira diferencirane materijale za čitanje iz bilo kojeg teksta, URL-a ili teme. Automatski prilagođava razinu jezične složenosti zadržavajući akademski sadržaj. Korisno za stvaranje verzija istog teksta za različite profile učenika.", rgpd_note: "Diffit (SAD): dostavljeni sadržaj može biti obrađen vanjskim modelima umjetne inteligencije. Ne unositi osobne podatke učenika; koristiti samo s anonimnim nastavnim sadržajem." },
    'elsa-speak': { desc: "AI trener izgovora engleskog jezika. Analizira govor korisnika i daje povratnu informaciju fonem po fonem. Posebno koristan za učenike engleskog kao J2 i nastavnike koji prepoznaju obrasce izgovora povezane s materinskim jezikom učenika.", rgpd_note: "ELSA Corp. (SAD): glasovni zapisi obrađuju se na njihovim poslužiteljima. Besplatna verzija ima ograničene funkcionalnosti; Pro je plaćena. Za maloljetnike provjeriti politiku privatnosti i dobiti roditeljski pristanak prije korištenja glasovnih podataka." },
    'grammarly': { desc: "AI asistent za pisanje koji ispravlja gramatiku, pravopis i interpunkciju te predlaže poboljšanja jasnoće i tona. Dostupan kao proširenje preglednika i integriran u Google Docs i Word.", rgpd_note: "Grammarly Inc. (SAD): podaci se šalju na američke poslužitelje. Besplatna verzija može koristiti tekstove za poboljšanje modela. Za osjetljiv sadržaj učenika ne koristiti tekstove s identificirajućim podacima. Poslovna verzija uključuje dodatne kontrole privatnosti." },
    'immersive-reader': { desc: "Besplatni imerzivni čitač integriran u Word, Teams, OneNote i Edge. Rastavlja slogove, naglašava vrste riječi, čita tekst naglas i prilagođava razmak i veličinu fonta. Radi izravno u razrednim dokumentima.", rgpd_note: "Integriran u Microsoftove proizvode: obrada podataka prati Microsoftovu politiku privatnosti za Microsoft 365. U školskom okruženju s licencijom Microsoft 365 Education podaci učenika tretiraju se kao školski podaci i ne koriste se za oglašavanje." },
    'khanmigo': { desc: "Besplatna platforma za učenje s AI tutorom (Khanmigo). AI tutor prilagođava objašnjenja tempu učenika, postavlja sokratska pitanja umjesto davanja izravnih odgovora i prati napredak. Posebno koristan za darovite učenike i za učenike s hrvatskim kao J2.", rgpd_note: "Khan Academy (SAD, neprofitna organizacija): podaci maloljetnih učenika zahtijevaju račun koji je izradio nastavnik ili skrbnik. Khan Academy ne prodaje podatke za oglašavanje. Khanmigo ima dodatni trošak za nastavnike; osnovna platforma je besplatna. Provjeriti usklađenost s GDPR-om za korištenje u EU." },
    'magicschool': { desc: "AI platforma dizajnirana posebno za nastavnike. Uključuje alate za diferenciranje nastavnih planova, izradu prilagodbi za učenike s posebnim odgojno-obrazovnim potrebama, generiranje komunikacije za roditelje i prilagođavanje materijala različitim razinama čitanja.", rgpd_note: "MagicSchool AI (SAD): platforma dizajnirana za obrazovni kontekst, COPPA/FERPA sukladna za američke škole. Za korištenje u EU provjeriti usklađenost s GDPR-om prije unosa podataka učenika. Koristiti samo s anonimnim ili izmišljenim podacima dok se ne potvrdi ugovor o obradi podataka sa školom." },
    'natural-reader': { desc: "Pretvara pisani tekst u sintetizirani govor. Korisno za učenike s disleksijom ili dispraksijom koji imaju koristi od slušne podrške tijekom čitanja.", rgpd_note: "Besplatna verzija je mrežna. Ne slati tekstove s osobno prepoznatljivim podacima učenika." },
    'notebooklm': { desc: "Googleov alat koji obrađuje dokumente i omogućuje postavljanje pitanja, generiranje sažetaka i izradu vodiča za učenje iz dostavljenih materijala. Koristan za prilagodbu dugih tekstova.", rgpd_note: "Googleov proizvod. Podaci se obrađuju prema uvjetima Google Workspacea. Ne učitavati dokumente s osobnim podacima učenika. Koristiti samo s anonimnim nastavnim materijalima." },
    'otter': { desc: "Automatska transkripcija zvuka u stvarnom vremenu. Korisno za učenike s ADHD-om ili poteškoćama slušne obrade da prate usmena objašnjenja, te za nastavnike koji izrađuju transkripte nastave.", rgpd_note: "Otter.ai (SAD): zvučni zapisi i transkripti pohranjuju se na njihovim poslužiteljima. Pribaviti informirani pristanak prije snimanja bilo kojeg sata. Besplatna verzija čuva snimke na neodređeno; potvrditi politiku zadržavanja. Ne snimati razgovore s maloljetnicima bez izričitog odobrenja." },
    'quizlet': { desc: "Platforma kartica za učenje i obrazovnih igara. AI funkcija automatski generira setove za učenje iz bilješki ili dokumenata. Učinkovito za konsolidiranje vokabulara i pojmova, posebno za profile s ograničenom radnom memorijom.", rgpd_note: "Quizlet Inc. (SAD): podaci o korištenju dijele se s trećim stranama u svrhu oglašavanja u besplatnoj verziji. Za učenike mlađe od 13 godina potreban je račun koji je izradio nastavnik (Quizlet Teacher). Verzija Plus ili School uklanja oglase i jača privatnost." },
    'speechify': { desc: "Visokokvalitetni pretvarač teksta u govor s prirodnim glasovima na više jezika. Čita PDF-ove, web stranice, dokumente i e-poštu. Omogućuje prilagođavanje brzine čitanja i ističe tekst dok se čita. Korisno za učenike s disleksijom ili dispraksijom.", rgpd_note: "Speechify Inc. (SAD): dostavljeni sadržaj obrađuje se na njihovim poslužiteljima. Besplatna verzija ima ograničenje minuta slušanja; Premium je plaćena. Za dokumente s podacima učenika koristiti samo anonimne nastavne tekstove." },
  },

  de: {
    'chatgpt': { desc: "Allgemein einsetzbares Sprachmodell. Nützlich zum Anpassen von Texten, Erstellen differenzierter Aufgaben, Entwickeln kontextualisierter Beispiele und Verfassen von Lernmaterialien.", rgpd_note: "Die kostenlose Version kann Gespräche zum Training des Modells nutzen. In den Einstellungen > Datenschutzeinstellungen deaktivieren. Nie Namen, Diagnosen oder identifizierende Schülerdaten einsenden. Für institutionelle Nutzung Teams- oder Enterprise-Plan mit Auftragsverarbeitungsvertrag (AVV) in Betracht ziehen." },
    'deepl': { desc: "Hochwertige maschinelle Übersetzung mit besonders starken Ergebnissen für europäische Sprachen. Für akademische Texte kontextuell präziser als Google Translate.", rgpd_note: "Die kostenlose Version sendet Text an externe Server (DeepL GmbH, Deutschland, innerhalb der EU). Die Pro-Version umfasst einen DSGVO-konformen Auftragsverarbeitungsvertrag. Nie Dokumente mit vollständigen Namen oder sensiblen Schülerdaten übersetzen." },
    'diffit': { desc: "Erstellt differenzierte Lesematerialien aus beliebigem Text, URLs oder Themen. Passt den sprachlichen Komplexitätsgrad automatisch an und behält dabei den fachlichen Inhalt bei. Nützlich, um verschiedene Versionen desselben Texts für unterschiedliche Schülerprofile zu erstellen.", rgpd_note: "Diffit (USA): eingereichte Inhalte können von externen KI-Modellen verarbeitet werden. Keine personenbezogenen Schülerdaten eingeben; nur mit anonymem Unterrichtsmaterial verwenden." },
    'elsa-speak': { desc: "KI-gestützter Aussprachetrainer für Englisch. Analysiert die Sprache des Nutzers und gibt phonemgenaues Feedback. Besonders hilfreich für Englischlernende als Zweitsprache und für Lehrkräfte, die Aussprachemuster in Zusammenhang mit der Muttersprache der Schüler identifizieren.", rgpd_note: "ELSA Corp. (USA): Sprachaufnahmen werden auf deren Servern verarbeitet. Die kostenlose Version hat eingeschränkte Funktionen; Pro ist kostenpflichtig. Bei Minderjährigen die Datenschutzrichtlinie prüfen und Elternzustimmung einholen, bevor Sprachdaten genutzt werden." },
    'grammarly': { desc: "KI-Schreibassistent, der Grammatik, Rechtschreibung und Zeichensetzung korrigiert und Verbesserungen für Klarheit und Ton vorschlägt. Als Browser-Erweiterung verfügbar und in Google Docs und Word integriert.", rgpd_note: "Grammarly Inc. (USA): Daten werden an US-Server übertragen. Die kostenlose Version kann Texte zur Modellverbesserung nutzen. Bei sensiblen Schülerinhalten keine Texte mit identifizierenden Daten verwenden. Die Business-Version bietet zusätzliche Datenschutzkontrollen." },
    'immersive-reader': { desc: "Kostenloser Immersive Reader, integriert in Word, Teams, OneNote und Edge. Trennt Silben, hebt Wortarten hervor, liest Text vor und passt Abstände und Schriftgröße an. Funktioniert direkt in Klassendokumenten.", rgpd_note: "In Microsoft-Produkte integriert: die Datenverarbeitung folgt der Microsoft-365-Datenschutzrichtlinie. In schulischen Umgebungen mit Microsoft 365 Education-Lizenz werden Schülerdaten als Schuldaten behandelt und nicht für Werbezwecke genutzt." },
    'khanmigo': { desc: "Kostenlose Lernplattform mit KI-Tutor (Khanmigo). Der KI-Tutor passt Erklärungen an das Lerntempo des Schülers an, stellt sokratische Fragen statt direkte Antworten zu geben und verfolgt Fortschritte. Besonders geeignet für hochbegabte Schüler und für Deutsch als Zweitsprache mit Inhalten in mehreren Sprachen.", rgpd_note: "Khan Academy (USA, gemeinnützig): Daten minderjähriger Schüler erfordern ein von einer Lehrkraft oder einem Erziehungsberechtigten erstelltes Konto. Khan Academy verkauft keine Daten für Werbezwecke. Khanmigo hat für Lehrkräfte zusätzliche Kosten; die Basisplattform ist kostenlos. DSGVO-Konformität für EU-Nutzung prüfen." },
    'magicschool': { desc: "KI-Plattform speziell für Lehrkräfte. Enthält Werkzeuge zur Differenzierung von Unterrichtseinheiten, zur Erstellung von Fördermaßnahmen für Schüler mit sonderpädagogischem Förderbedarf, zum Erstellen von Elternkommunikation und zur Anpassung von Materialien an verschiedene Lesestufen.", rgpd_note: "MagicSchool AI (USA): für den Bildungskontext entwickelte Plattform, COPPA/FERPA-konform für US-Schulen. Für EU-Nutzung DSGVO-Konformität vor Eingabe von Schülerdaten prüfen. Bis zur Bestätigung eines AVV mit der Schule nur anonyme oder fiktive Daten verwenden." },
    'natural-reader': { desc: "Wandelt geschriebenen Text in synthetische Sprache um. Nützlich für Schüler mit Legasthenie oder Dyspraxie, die beim Lesen von auditiver Unterstützung profitieren.", rgpd_note: "Die kostenlose Version ist webbasiert. Keine Texte mit personenbezogenen Schülerdaten einreichen." },
    'notebooklm': { desc: "Google-Werkzeug, das Dokumente verarbeitet und das Stellen von Fragen, das Erstellen von Zusammenfassungen und das Anlegen von Lernleitfäden aus dem hochgeladenen Material ermöglicht. Nützlich zur Anpassung langer Texte.", rgpd_note: "Google-Produkt. Daten werden gemäß den Google-Workspace-Nutzungsbedingungen verarbeitet. Keine Dokumente mit persönlichen Schülerdaten hochladen. Nur mit anonymem Unterrichtsmaterial verwenden." },
    'otter': { desc: "Automatische Echtzeit-Audiotypmittlung. Nützlich für Schüler mit ADHS oder auditiven Verarbeitungsschwierigkeiten, um mündlichen Erklärungen zu folgen, und für Lehrkräfte, die überprüfbare Unterrichtsprotokolle erstellen.", rgpd_note: "Otter.ai (USA): Audioaufnahmen und Transkripte werden auf deren Servern gespeichert. Vor jeder Aufnahme eine informierte Einwilligung einholen. Die kostenlose Version speichert Aufnahmen auf unbestimmte Zeit; Aufbewahrungsrichtlinie bestätigen. Keine Gespräche mit Minderjährigen ohne ausdrückliche Genehmigung aufzeichnen." },
    'quizlet': { desc: "Plattform für Lernkarten und Lernspiele. Die KI-Funktion erstellt automatisch Lernsets aus Notizen oder Dokumenten. Effektiv zur Festigung von Vokabular und Konzepten, besonders für Profile mit eingeschränktem Arbeitsgedächtnis.", rgpd_note: "Quizlet Inc. (USA): Nutzungsdaten werden in der kostenlosen Version zu Werbezwecken mit Dritten geteilt. Für Schüler unter 13 Jahren ist ein von der Lehrkraft erstelltes Konto erforderlich (Quizlet Teacher). Die Plus- oder School-Version entfernt Werbung und stärkt den Datenschutz." },
    'speechify': { desc: "Hochwertiger Text-zu-Sprache-Konverter mit natürlichen Stimmen in mehreren Sprachen. Liest PDFs, Webseiten, Dokumente und E-Mails vor. Ermöglicht die Anpassung der Lesegeschwindigkeit und hebt den Text beim Vorlesen hervor. Nützlich für Schüler mit Legasthenie oder Dyspraxie.", rgpd_note: "Speechify Inc. (USA): eingereichte Inhalte werden auf deren Servern verarbeitet. Die kostenlose Version hat ein Minutenlimit für das Zuhören; Premium ist kostenpflichtig. Für Dokumente mit Schülerdaten nur anonyme Unterrichtstexte verwenden." },
  },

  nl: {
    'chatgpt': { desc: "Taalmodel voor algemeen gebruik. Handig voor het aanpassen van teksten, het genereren van gedifferentieerde oefeningen, het maken van gecontextualiseerde voorbeelden en het opstellen van ondersteuningsmateriaal.", rgpd_note: "De gratis versie kan gesprekken gebruiken om het model te trainen. Uitschakelen in Instellingen > Gegevensbeheer. Nooit namen, diagnoses of identificerende leerlinggegevens versturen. Voor institutioneel gebruik het Teams- of Enterprise-plan overwegen met een verwerkersovereenkomst." },
    'deepl': { desc: "Hoogwaardige automatische vertaling met uitstekende prestaties voor Europese talen. Contextueel nauwkeuriger dan Google Translate voor academische teksten.", rgpd_note: "De gratis versie stuurt tekst naar externe servers (DeepL GmbH, Duitsland, binnen de EU). De Pro-versie bevat een AVG-conform verwerkingscontract. Nooit documenten vertalen met volledige namen of gevoelige leerlinggegevens." },
    'diffit': { desc: "Genereert gedifferentieerde leesmaterialen van elke tekst, URL of onderwerp. Past automatisch het talig complexiteitsniveau aan met behoud van academische inhoud. Handig voor het maken van versies van dezelfde tekst voor verschillende leerlingprofielen.", rgpd_note: "Diffit (VS): ingediende inhoud kan worden verwerkt door externe AI-modellen. Geen persoonlijke leerlinggegevens invoeren; alleen gebruiken met anoniem cursulusmateriaal." },
    'elsa-speak': { desc: "AI-uitspraaktrainer voor Engels. Analyseert de spraak van de gebruiker en geeft foneem-voor-foneem feedback. Bijzonder nuttig voor leerders van Engels als tweede taal en voor leraren die uitspraakmuster herkennen die verband houden met de moedertaal van de leerling.", rgpd_note: "ELSA Corp. (VS): spraakopnames worden verwerkt op hun servers. De gratis versie heeft beperkte functies; Pro is betaald. Voor minderjarigen het privacybeleid controleren en ouderlijke toestemming verkrijgen voor gebruik van spraakgegevens." },
    'grammarly': { desc: "AI-schrijfassistent die grammatica, spelling en interpunctie corrigeert en verbeteringen voor duidelijkheid en toon voorstelt. Beschikbaar als browserextensie en geïntegreerd in Google Docs en Word.", rgpd_note: "Grammarly Inc. (VS): gegevens verzonden naar Amerikaanse servers. De gratis versie kan teksten gebruiken om het model te verbeteren. Geen teksten met identificerende gegevens gebruiken voor gevoelige leerlinginhoud. De Business-versie bevat aanvullende privacycontroles." },
    'immersive-reader': { desc: "Gratis immersive reader geïntegreerd in Word, Teams, OneNote en Edge. Splitst lettergrepen, markeert woordsoorten, leest tekst voor en past spatiëring en lettergrootte aan. Werkt direct in klassikale documenten.", rgpd_note: "Geïntegreerd in Microsoft-producten: gegevensverwerking volgt het Microsoft 365-privacybeleid. In schoolomgevingen met Microsoft 365 Education-licentie worden leerlinggegevens behandeld als schoolgegevens en niet gebruikt voor advertenties." },
    'khanmigo': { desc: "Gratis leerplatform met AI-tutor (Khanmigo). De AI-tutor past uitleg aan op het tempo van de leerling, stelt socratische vragen in plaats van directe antwoorden te geven en volgt de voortgang. Bijzonder nuttig voor hoogbegaafde leerlingen en voor leerders van Nederlands als tweede taal.", rgpd_note: "Khan Academy (VS, non-profit): leerlinggegevens van minderjarigen vereisen een account aangemaakt door een leraar of voogd. Khan Academy verkoopt geen gegevens voor advertenties. Khanmigo heeft extra kosten voor leraren; het basisplatform is gratis. AVG-conformiteit voor EU-gebruik controleren." },
    'magicschool': { desc: "AI-platform speciaal ontworpen voor leraren. Bevat tools om lesplannen te differentiëren, aanpassingen te maken voor leerlingen met extra ondersteuningsbehoeften, communicatie voor ouders te genereren en materialen aan te passen aan verschillende leesniveaus.", rgpd_note: "MagicSchool AI (VS): platform ontworpen voor onderwijscontext, COPPA/FERPA-conform voor Amerikaanse scholen. Voor EU-gebruik AVG-conformiteit controleren voor invoer van leerlinggegevens. Alleen anonieme of fictieve gegevens gebruiken totdat een verwerkersovereenkomst met de school bevestigd is." },
    'natural-reader': { desc: "Zet geschreven tekst om in gesynthetiseerde spraak. Handig voor leerlingen met dyslexie of dyspraxie die baat hebben bij auditieve ondersteuning tijdens het lezen.", rgpd_note: "De gratis versie is webgebaseerd. Geen teksten indienen met persoonlijk identificeerbare leerlinggegevens." },
    'notebooklm': { desc: "Google-tool die documenten verwerkt en vragen beantwoorden, samenvattingen genereren en studiegidsen maken uit geüpload materiaal mogelijk maakt. Handig voor het aanpassen van lange teksten.", rgpd_note: "Google-product. Gegevens verwerkt onder Google Workspace-voorwaarden. Geen documenten uploaden met persoonlijke leerlinggegevens. Alleen gebruiken met anoniem lesmateriaal." },
    'otter': { desc: "Automatische real-time audiotranscriptie. Handig voor leerlingen met ADHD of auditieve verwerkingsproblemen om mondelinge uitleg te volgen, en voor leraren die herhaalbare lestranscripties maken.", rgpd_note: "Otter.ai (VS): audio-opnames en transcripties opgeslagen op hun servers. Geïnformeerde toestemming verkrijgen voor het opnemen van een les. De gratis versie bewaart opnames voor onbepaalde tijd; bewaarbeleid bevestigen. Geen gesprekken met minderjarigen opnemen zonder uitdrukkelijke toestemming." },
    'quizlet': { desc: "Platform voor flashcards en leerspelen. De AI-functie genereert automatisch studiesets uit aantekeningen of documenten. Effectief voor het consolideren van woordenschat en concepten, vooral voor profielen met beperkt werkgeheugen.", rgpd_note: "Quizlet Inc. (VS): gebruiksgegevens gedeeld met derden voor advertentiedoeleinden in de gratis versie. Voor leerlingen jonger dan 13 jaar is een door de leraar aangemaakt account vereist (Quizlet Teacher). De Plus- of School-versie verwijdert advertenties en versterkt de privacy." },
    'speechify': { desc: "Hoogwaardige tekst-naar-spraakconverter met natuurlijke stemmen in meerdere talen. Leest pdf's, webpagina's, documenten en e-mails voor. Maakt aanpassing van leessnelheid mogelijk en markeert tekst terwijl het wordt voorgelezen. Nuttig voor leerlingen met dyslexie of dyspraxie.", rgpd_note: "Speechify Inc. (VS): ingediende inhoud verwerkt op hun servers. De gratis versie heeft een limiet voor luisterminuten; Premium is betaald. Voor documenten met leerlinggegevens alleen anonieme lesteksten gebruiken." },
  },

  pl: {
    'chatgpt': { desc: "Model językowy do użytku ogólnego. Przydatny do adaptowania tekstów, generowania zróżnicowanych ćwiczeń, tworzenia skonkretyzowanych przykładów i przygotowywania materiałów wspierających.", rgpd_note: "Bezpłatna wersja może wykorzystywać rozmowy do trenowania modelu. Wyłączyć w Ustawieniach > Kontrola danych. Nigdy nie przesyłać imion i nazwisk, diagnoz ani danych identyfikujących uczniów. Do użytku instytucjonalnego rozważyć plan Teams lub Enterprise z umową powierzenia przetwarzania danych." },
    'deepl': { desc: "Wysokiej jakości tłumaczenie automatyczne z doskonałymi wynikami dla języków europejskich. Bardziej precyzyjne kontekstowo niż Google Tłumacz dla tekstów akademickich.", rgpd_note: "Bezpłatna wersja wysyła tekst na zewnętrzne serwery (DeepL GmbH, Niemcy, w UE). Wersja Pro zawiera umowę powierzenia przetwarzania danych zgodną z RODO. Nigdy nie tłumaczyć dokumentów zawierających pełne imiona lub wrażliwe dane uczniów." },
    'diffit': { desc: "Generuje zróżnicowane materiały do czytania z dowolnego tekstu, adresu URL lub tematu. Automatycznie dostosowuje poziom złożoności językowej, zachowując treść akademicką. Przydatne do tworzenia wersji tego samego tekstu dla różnych profili uczniów.", rgpd_note: "Diffit (USA): przesłane treści mogą być przetwarzane przez zewnętrzne modele AI. Nie wprowadzać danych osobowych uczniów; używać wyłącznie z anonimowymi treściami programowymi." },
    'elsa-speak': { desc: "Trener wymowy angielskiego z AI. Analizuje mowę użytkownika i podaje informację zwrotną fonem po fonemie. Szczególnie przydatny dla uczących się angielskiego jako J2 i dla nauczycieli identyfikujących wzorce wymowy związane z językiem ojczystym ucznia.", rgpd_note: "ELSA Corp. (USA): nagrania głosowe przetwarzane na ich serwerach. Bezpłatna wersja ma ograniczone funkcje; Pro jest płatna. Dla niepełnoletnich sprawdzić politykę prywatności i uzyskać zgodę rodziców przed użyciem danych głosowych." },
    'grammarly': { desc: "Asystent pisania AI, który koryguje gramatykę, pisownię i interpunkcję oraz sugeruje ulepszenia jasności i tonu. Dostępny jako rozszerzenie przeglądarki, zintegrowany z Google Docs i Wordem.", rgpd_note: "Grammarly Inc. (USA): dane przesyłane na serwery w USA. Bezpłatna wersja może używać tekstów do ulepszania modelu. Dla wrażliwych treści uczniów nie używać tekstów z danymi identyfikującymi. Wersja Business zawiera dodatkowe kontrole prywatności." },
    'immersive-reader': { desc: "Bezpłatny czytnik immersyjny zintegrowany z Wordem, Teams, OneNote i Edge. Dzieli wyrazy na sylaby, podkreśla części mowy, czyta tekst na głos i dostosowuje odstępy i rozmiar czcionki. Działa bezpośrednio w dokumentach klasowych.", rgpd_note: "Zintegrowany z produktami Microsoft: przetwarzanie danych odbywa się zgodnie z polityką prywatności Microsoft 365. W środowisku szkolnym z licencją Microsoft 365 Education dane uczniów traktowane są jako dane szkolne i nie są wykorzystywane do celów reklamowych." },
    'khanmigo': { desc: "Bezpłatna platforma edukacyjna z tutorem AI (Khanmigo). Tutor AI dostosowuje wyjaśnienia do tempa ucznia, zadaje pytania sokratejskie zamiast udzielać bezpośrednich odpowiedzi i śledzi postępy. Szczególnie przydatny dla uczniów zdolnych i dla uczących się polskiego jako J2.", rgpd_note: "Khan Academy (USA, organizacja non-profit): dane małoletnich uczniów wymagają konta założonego przez nauczyciela lub opiekuna. Khan Academy nie sprzedaje danych w celach reklamowych. Khanmigo ma dodatkowy koszt dla nauczycieli; platforma podstawowa jest bezpłatna. Sprawdzić zgodność z RODO do użytku w UE." },
    'magicschool': { desc: "Platforma AI zaprojektowana specjalnie dla nauczycieli. Zawiera narzędzia do różnicowania planów lekcji, tworzenia dostosowań dla uczniów ze specjalnymi potrzebami edukacyjnymi, generowania komunikacji dla rodziców i dostosowywania materiałów do różnych poziomów czytania.", rgpd_note: "MagicSchool AI (USA): platforma przeznaczona dla kontekstu edukacyjnego, zgodna z COPPA/FERPA dla szkół amerykańskich. Do użytku w UE sprawdzić zgodność z RODO przed wprowadzeniem danych uczniów. Używać wyłącznie z danymi anonimowymi lub fikcyjnymi do czasu potwierdzenia umowy powierzenia z placówką." },
    'natural-reader': { desc: "Przetwarza tekst pisany na syntezowany głos. Przydatny dla uczniów z dysleksją lub dyspraksją, którzy korzystają z wsparcia słuchowego podczas czytania.", rgpd_note: "Bezpłatna wersja jest aplikacją internetową. Nie przesyłać tekstów z danymi osobowymi identyfikującymi uczniów." },
    'notebooklm': { desc: "Narzędzie Google, które przetwarza dokumenty i umożliwia zadawanie pytań, generowanie streszczeń oraz tworzenie przewodników do nauki z przesłanego materiału. Przydatne do adaptowania długich tekstów.", rgpd_note: "Produkt Google. Dane przetwarzane zgodnie z warunkami Google Workspace. Nie przesyłać dokumentów zawierających dane osobowe uczniów. Używać wyłącznie z anonimowymi materiałami programowymi." },
    'otter': { desc: "Automatyczna transkrypcja audio w czasie rzeczywistym. Przydatna dla uczniów z ADHD lub trudnościami przetwarzania słuchowego do śledzenia ustnych wyjaśnień oraz dla nauczycieli tworzących transkrypcje lekcji do powtarzania.", rgpd_note: "Otter.ai (USA): nagrania audio i transkrypcje przechowywane na ich serwerach. Uzyskać świadomą zgodę przed nagrywaniem jakiejkolwiek lekcji. Bezpłatna wersja przechowuje nagrania bezterminowo; potwierdzić politykę przechowywania. Nie nagrywać rozmów z małoletnimi bez wyraźnej autoryzacji." },
    'quizlet': { desc: "Platforma fiszek i gier edukacyjnych. Funkcja AI automatycznie generuje zestawy do nauki z notatek lub dokumentów. Skuteczna w utrwalaniu słownictwa i pojęć, szczególnie dla profili z ograniczoną pamięcią roboczą.", rgpd_note: "Quizlet Inc. (USA): dane użytkowania udostępniane stronom trzecim w celach reklamowych w wersji bezpłatnej. Dla uczniów poniżej 13 lat wymagane jest konto założone przez nauczyciela (Quizlet Teacher). Wersja Plus lub School usuwa reklamy i wzmacnia prywatność." },
    'speechify': { desc: "Wysokiej jakości konwerter tekstu na mowę z naturalnymi głosami w wielu językach. Czyta pliki PDF, strony internetowe, dokumenty i e-maile. Umożliwia dostosowanie prędkości czytania i podkreśla tekst podczas czytania. Przydatny dla uczniów z dysleksją lub dyspraksją.", rgpd_note: "Speechify Inc. (USA): przesłane treści przetwarzane na ich serwerach. Bezpłatna wersja ma limit minut słuchania; Premium jest płatna. Dla dokumentów z danymi uczniów używać wyłącznie anonimowych tekstów programowych." },
  },

  ro: {
    'chatgpt': { desc: "Model de limbaj de uz general. Util pentru adaptarea textelor, generarea de exerciții diferențiate, crearea de exemple contextualizate și redactarea materialelor de sprijin.", rgpd_note: "Versiunea gratuită poate folosi conversațiile pentru antrenarea modelului. Dezactivați în Setări > Controale date. Nu trimiteți niciodată nume, diagnostice sau date identificabile ale elevilor. Pentru uz instituțional, luați în considerare planul Teams sau Enterprise cu un acord de prelucrare a datelor." },
    'deepl': { desc: "Traducere automată de înaltă calitate, cu performanță superioară pentru limbile europene. Mai precis contextual decât Google Translate pentru texte academice.", rgpd_note: "Versiunea gratuită trimite text către servere externe (DeepL GmbH, Germania, în UE). Versiunea Pro include un contract de prelucrare a datelor conform GDPR. Nu traduceți niciodată documente cu nume complete sau date sensibile ale elevilor." },
    'diffit': { desc: "Generează materiale de lectură diferențiate din orice text, URL sau subiect. Adaptează automat nivelul de complexitate lingvistică păstrând conținutul academic. Util pentru crearea de versiuni ale aceluiași text pentru diferite profiluri de elevi.", rgpd_note: "Diffit (SUA): conținutul trimis poate fi procesat de modele AI externe. Nu introduceți date personale ale elevilor; folosiți doar cu conținut curricular anonim." },
    'elsa-speak': { desc: "Antrenor de pronunție a limbii engleze cu AI. Analizează vorbirea utilizatorului și oferă feedback fonem cu fonem. Deosebit de util pentru cei care învață engleza ca L2 și pentru profesori care identifică tipare de pronunție legate de limba maternă a elevului.", rgpd_note: "ELSA Corp. (SUA): înregistrările vocale sunt procesate pe serverele lor. Versiunea gratuită are funcționalități limitate; Pro este cu plată. Pentru minori, verificați politica de confidențialitate și obțineți consimțământul părinților înainte de a utiliza date vocale." },
    'grammarly': { desc: "Asistent de scriere cu AI care corectează gramatica, ortografia și punctuația și sugerează îmbunătățiri ale clarității și tonului. Disponibil ca extensie de browser și integrat în Google Docs și Word.", rgpd_note: "Grammarly Inc. (SUA): date trimise pe servere americane. Versiunea gratuită poate folosi textele pentru îmbunătățirea modelului. Pentru conținut sensibil al elevilor, nu folosiți texte cu date identificabile. Versiunea Business include controale suplimentare de confidențialitate." },
    'immersive-reader': { desc: "Cititor imersiv gratuit integrat în Word, Teams, OneNote și Edge. Separă silabele, evidențiază părțile de vorbire, citește textul cu voce tare și ajustează spațierea și dimensiunea fontului. Funcționează direct în documentele clasei.", rgpd_note: "Integrat în produsele Microsoft: prelucrarea datelor urmează politica de confidențialitate Microsoft 365. În medii școlare cu licență Microsoft 365 Education, datele elevilor sunt tratate ca date școlare și nu sunt utilizate pentru publicitate." },
    'khanmigo': { desc: "Platformă de învățare gratuită cu tutor AI (Khanmigo). Tutorul AI adaptează explicațiile la ritmul elevului, pune întrebări socratice în loc să dea răspunsuri directe și urmărește progresul. Deosebit de util pentru elevii supradotați și pentru cei care învață româna ca L2.", rgpd_note: "Khan Academy (SUA, organizație non-profit): datele elevilor minori necesită un cont creat de un profesor sau tutore. Khan Academy nu vinde date în scopuri publicitare. Khanmigo are un cost suplimentar pentru profesori; platforma de bază este gratuită. Verificați conformitatea GDPR pentru utilizarea în UE." },
    'magicschool': { desc: "Platformă AI concepută special pentru profesori. Include instrumente pentru diferențierea planurilor de lecție, crearea de adaptări pentru elevii cu cerințe educative speciale, generarea de comunicări pentru părinți și adaptarea materialelor la diferite niveluri de lectură.", rgpd_note: "MagicSchool AI (SUA): platformă concepută pentru contextul educațional, conformă COPPA/FERPA pentru școlile americane. Pentru utilizarea în UE, verificați conformitatea GDPR înainte de a introduce date ale elevilor. Folosiți doar date anonime sau fictive până la confirmarea unui acord de prelucrare a datelor cu școala." },
    'natural-reader': { desc: "Convertește textul scris în voce sintetizată. Util pentru elevii cu dislexie sau dispraxie care beneficiază de sprijin auditiv în timpul lecturii.", rgpd_note: "Versiunea gratuită este bazată pe web. Nu trimiteți texte cu date personale identificabile ale elevilor." },
    'notebooklm': { desc: "Instrument Google care procesează documente și permite adresarea de întrebări, generarea de rezumate și crearea de ghiduri de studiu din materialul încărcat. Util pentru adaptarea textelor lungi.", rgpd_note: "Produs Google. Date procesate conform termenilor Google Workspace. Nu încărcați documente cu date personale ale elevilor. Folosiți doar cu materiale curriculare anonime." },
    'otter': { desc: "Transcriere automată audio în timp real. Util pentru elevii cu ADHD sau dificultăți de procesare auditivă pentru a urmări explicațiile orale și pentru profesori care creează transcrieri ale lecțiilor de revizuit.", rgpd_note: "Otter.ai (SUA): înregistrările audio și transcrierile sunt stocate pe serverele lor. Obțineți consimțământul informat înainte de a înregistra orice lecție. Versiunea gratuită stochează înregistrările pe termen nelimitat; confirmați politica de retenție. Nu înregistrați conversații cu minori fără autorizație explicită." },
    'quizlet': { desc: "Platformă de carduri de studiu și jocuri de învățare. Funcția AI generează automat seturi de studiu din notițe sau documente. Eficientă pentru consolidarea vocabularului și a conceptelor, în special pentru profiluri cu memorie de lucru limitată.", rgpd_note: "Quizlet Inc. (SUA): datele de utilizare sunt partajate cu terți în scopuri publicitare în versiunea gratuită. Pentru elevii sub 13 ani este necesar un cont creat de profesor (Quizlet Teacher). Versiunea Plus sau School elimină reclamele și întărește confidențialitatea." },
    'speechify': { desc: "Convertor text-în-vorbire de înaltă calitate cu voci naturale în mai multe limbi. Citește fișiere PDF, pagini web, documente și e-mailuri. Permite ajustarea vitezei de citire și evidențiază textul pe măsură ce este citit. Util pentru elevii cu dislexie sau dispraxie.", rgpd_note: "Speechify Inc. (SUA): conținutul trimis este procesat pe serverele lor. Versiunea gratuită are o limită de minute de ascultare; Premium este cu plată. Pentru documentele cu date ale elevilor, folosiți doar texte curriculare anonime." },
  },

  cs: {
    'chatgpt': { desc: "Jazykový model pro obecné použití. Vhodný k přizpůsobení textů, vytváření diferencovaných cvičení, tvorbě kontextualizovaných příkladů a přípravě podpůrných materiálů.", rgpd_note: "Bezplatná verze může využívat konverzace k trénování modelu. Deaktivovat v Nastavení > Ovládání dat. Nikdy nezasílat jména, diagnózy ani identifikující údaje žáků. Pro institucionální využití zvážit plán Teams nebo Enterprise se smlouvou o zpracování dat." },
    'deepl': { desc: "Vysoce kvalitní strojový překlad s vynikajícími výsledky pro evropské jazyky. Kontextově přesnější než Google Překladač pro akademické texty.", rgpd_note: "Bezplatná verze odesílá text na externí servery (DeepL GmbH, Německo, v EU). Verze Pro zahrnuje smlouvu o zpracování dat v souladu s GDPR. Nikdy nepřekládat dokumenty s celými jmény nebo citlivými údaji žáků." },
    'diffit': { desc: "Generuje diferencované čtenářské materiály z jakéhokoli textu, URL nebo tématu. Automaticky upravuje úroveň jazykové složitosti při zachování akademického obsahu. Vhodné pro tvorbu různých verzí téhož textu pro různé profily žáků.", rgpd_note: "Diffit (USA): odeslaný obsah může být zpracován externími modely AI. Nezadávat osobní údaje žáků; používat pouze s anonymním kurikulárním obsahem." },
    'elsa-speak': { desc: "Trenér výslovnosti angličtiny s AI. Analyzuje řeč uživatele a poskytuje zpětnou vazbu foném po fonému. Zvláště užitečné pro žáky učící se angličtinu jako J2 a pro učitele identifikující vzorce výslovnosti spojené s mateřským jazykem žáka.", rgpd_note: "ELSA Corp. (USA): hlasové nahrávky zpracovávány na jejich serverech. Bezplatná verze má omezené funkce; Pro je placená. U nezletilých zkontrolovat zásady ochrany osobních údajů a před použitím hlasových dat získat souhlas rodičů." },
    'grammarly': { desc: "Asistent psaní s AI opravující gramatiku, pravopis a interpunkci a navrhující zlepšení srozumitelnosti a tónu. Dostupný jako rozšíření prohlížeče a integrovaný do Google Docs a Wordu.", rgpd_note: "Grammarly Inc. (USA): data odesílána na americké servery. Bezplatná verze může texty využívat ke zlepšení modelu. U citlivého obsahu žáků nepoužívat texty s identifikujícími údaji. Verze Business obsahuje další ovládání ochrany soukromí." },
    'immersive-reader': { desc: "Bezplatný imerzivní čtenář integrovaný ve Wordu, Teams, OneNote a Edge. Dělí slova na slabiky, zvýrazňuje slovní druhy, čte text nahlas a upravuje mezery a velikost písma. Funguje přímo v třídních dokumentech.", rgpd_note: "Integrován do produktů Microsoft: zpracování dat se řídí zásadami ochrany osobních údajů Microsoft 365. Ve školním prostředí s licencí Microsoft 365 Education jsou data žáků zpracovávána jako školní data a nejsou používána pro reklamní účely." },
    'khanmigo': { desc: "Bezplatná vzdělávací platforma s AI tutorem (Khanmigo). AI tutor přizpůsobuje vysvětlení tempu žáka, klade sokratovské otázky místo přímých odpovědí a sleduje pokrok. Zvláště vhodné pro nadané žáky a pro žáky s češtinou jako J2.", rgpd_note: "Khan Academy (USA, nezisková organizace): data nezletilých žáků vyžadují účet vytvořený učitelem nebo zákonným zástupcem. Khan Academy neprodává data pro reklamní účely. Khanmigo má pro učitele příplatek; základní platforma je zdarma. Ověřit shodu s GDPR pro použití v EU." },
    'magicschool': { desc: "AI platforma navržená speciálně pro učitele. Obsahuje nástroje pro diferenciaci výukových plánů, tvorbu adaptací pro žáky se speciálními vzdělávacími potřebami, generování komunikace pro rodiče a přizpůsobení materiálů různým úrovním čtení.", rgpd_note: "MagicSchool AI (USA): platforma určená pro vzdělávací kontext, shoda s COPPA/FERPA pro americké školy. Pro použití v EU ověřit shodu s GDPR před zadáváním dat žáků. Používat pouze anonymní nebo fiktivní data do potvrzení smlouvy o zpracování dat se školou." },
    'natural-reader': { desc: "Převádí psaný text na syntetizovaný hlas. Vhodné pro žáky s dyslexií nebo dyspraxií, kteří profitují ze zvukové podpory při čtení.", rgpd_note: "Bezplatná verze je webová aplikace. Nezasílat texty s osobně identifikovatelnými údaji žáků." },
    'notebooklm': { desc: "Nástroj Google, který zpracovává dokumenty a umožňuje pokládat otázky, generovat shrnutí a vytvářet studijní průvodce z nahraného materiálu. Vhodné k přizpůsobení dlouhých textů.", rgpd_note: "Produkt Google. Data zpracovávána dle podmínek Google Workspace. Nenahrávat dokumenty s osobními údaji žáků. Používat pouze s anonymními kurikulárními materiály." },
    'otter': { desc: "Automatický přepis zvuku v reálném čase. Vhodné pro žáky s ADHD nebo obtížemi se sluchovým zpracováním při sledování ústního výkladu a pro učitele vytvářející záznamy hodin k opakování.", rgpd_note: "Otter.ai (USA): zvukové nahrávky a přepisy uloženy na jejich serverech. Před nahráváním jakékoli hodiny získat informovaný souhlas. Bezplatná verze ukládá nahrávky na dobu neurčitou; potvrdit zásady uchovávání. Nenahrávat rozhovory s nezletilými bez výslovného souhlasu." },
    'quizlet': { desc: "Platforma pro studijní kartičky a vzdělávací hry. Funkce AI automaticky generuje studijní sady z poznámek nebo dokumentů. Efektivní pro upevňování slovní zásoby a pojmů, zvláště pro profily s omezenou pracovní pamětí.", rgpd_note: "Quizlet Inc. (USA): data o využití sdílena s třetími stranami pro reklamní účely v bezplatné verzi. Pro žáky mladší 13 let je vyžadován účet vytvořený učitelem (Quizlet Teacher). Verze Plus nebo School odstraňuje reklamy a posiluje ochranu soukromí." },
    'speechify': { desc: "Vysoce kvalitní převodník textu na řeč s přirozenými hlasy v několika jazycích. Čte PDF, webové stránky, dokumenty a e-maily. Umožňuje nastavit rychlost čtení a zvýrazňuje text při čtení. Vhodné pro žáky s dyslexií nebo dyspraxií.", rgpd_note: "Speechify Inc. (USA): odeslaný obsah zpracováván na jejich serverech. Bezplatná verze má limit poslechových minut; Premium je placená. Pro dokumenty s daty žáků používat pouze anonymní výukové texty." },
  },

  sv: {
    'chatgpt': { desc: "Allmänt språkmodell. Användbart för att anpassa texter, skapa differentierade övningar, ta fram kontextualiserade exempel och utarbeta stödmaterial.", rgpd_note: "Den kostnadsfria versionen kan använda konversationer för att träna modellen. Stäng av under Inställningar > Datakontroller. Skicka aldrig elevers namn, diagnoser eller identifierande uppgifter. För institutionellt bruk överväg Teams- eller Enterprise-planen med ett personuppgiftsbiträdesavtal." },
    'deepl': { desc: "Högkvalitativ maskinöversättning med utmärkta resultat för europeiska språk. Mer kontextuellt korrekt än Google Translate för akademiska texter.", rgpd_note: "Den kostnadsfria versionen skickar text till externa servrar (DeepL GmbH, Tyskland, inom EU). Pro-versionen inkluderar ett GDPR-kompatibelt databehandlingsavtal. Översätt aldrig dokument med fullständiga namn eller känsliga elevuppgifter." },
    'diffit': { desc: "Skapar differentierat läsmaterial från valfri text, URL eller ämne. Anpassar automatiskt den språkliga komplexitetsnivån medan det akademiska innehållet behålls. Användbart för att skapa versioner av samma text för olika elevprofiler.", rgpd_note: "Diffit (USA): inskickat innehåll kan bearbetas av externa AI-modeller. Ange inte personliga elevuppgifter; använd enbart med anonymt kursmaterial." },
    'elsa-speak': { desc: "AI-baserad uttalstränare för engelska. Analyserar användarens tal och ger återkoppling fonem för fonem. Särskilt användbart för elever som lär sig engelska som andraspråk och för lärare som identifierar uttalsmönster kopplade till elevens modersmål.", rgpd_note: "ELSA Corp. (USA): röstinspelningar bearbetas på deras servrar. Gratisversionen har begränsade funktioner; Pro är betald. För minderåriga kontrollera integritetspolicyn och inhämta föräldrarnas samtycke innan röstdata används." },
    'grammarly': { desc: "AI-skrivassistent som rättar grammatik, stavning och interpunktion samt föreslår förbättringar av tydlighet och ton. Tillgänglig som webbläsartillägg och integrerat i Google Docs och Word.", rgpd_note: "Grammarly Inc. (USA): data skickas till amerikanska servrar. Gratisversionen kan använda texter för att förbättra modellen. Använd inte texter med identifierande uppgifter för känsligt elevinnehåll. Business-versionen har ytterligare integritetskontroller." },
    'immersive-reader': { desc: "Kostnadsfri immersiv läsare integrerad i Word, Teams, OneNote och Edge. Delar upp ord i stavelser, markerar ordklasser, läser text högt och justerar radavstånd och teckenstorlek. Fungerar direkt i klassdokument.", rgpd_note: "Integrerad i Microsofts produkter: databehandling följer Microsoft 365:s integritetspolicy. I skolmiljöer med Microsoft 365 Education-licens behandlas elevdata som skoldata och används inte för reklam." },
    'khanmigo': { desc: "Kostnadsfri lärplattform med AI-tutor (Khanmigo). AI-tutorn anpassar förklaringar till elevens tempo, ställer sokratiska frågor istället för att ge direkta svar och följer framstegen. Särskilt användbart för högpresterande elever och för elever med svenska som andraspråk.", rgpd_note: "Khan Academy (USA, ideell organisation): data för minderåriga elever kräver ett konto skapat av en lärare eller vårdnadshavare. Khan Academy säljer inte data för reklamändamål. Khanmigo har extra kostnad för lärare; grundplattformen är gratis. Kontrollera GDPR-överensstämmelse för EU-bruk." },
    'magicschool': { desc: "AI-plattform utformad specifikt för lärare. Inkluderar verktyg för att differentiera lektionsplaneringar, skapa anpassningar för elever med särskilda behov, generera kommunikation till föräldrar och anpassa material till olika läsnivåer.", rgpd_note: "MagicSchool AI (USA): plattform utformad för utbildningskontext, COPPA/FERPA-kompatibel för amerikanska skolor. För EU-bruk kontrollera GDPR-överensstämmelse innan elevdata anges. Använd bara anonyma eller fiktiva data tills ett personuppgiftsbiträdesavtal bekräftats med skolan." },
    'natural-reader': { desc: "Konverterar skriven text till syntetiserat tal. Användbart för elever med dyslexi eller dyspraxi som gynnas av auditiv stöttning under läsning.", rgpd_note: "Gratisversionen är webbaserad. Skicka inte texter med personligt identifierbara elevuppgifter." },
    'notebooklm': { desc: "Googles verktyg som bearbetar dokument och möjliggör frågor, generering av sammanfattningar och skapande av studievägledningar från uppladdade material. Användbart för att anpassa långa texter.", rgpd_note: "Google-produkt. Data bearbetas enligt Google Workspace-villkor. Ladda inte upp dokument med personliga elevuppgifter. Använd enbart med anonymt kursmaterial." },
    'otter': { desc: "Automatisk transkription av ljud i realtid. Användbart för elever med ADHD eller auditiva bearbetningssvårigheter för att följa muntliga genomgångar, och för lärare som skapar lektionstransskript för repetition.", rgpd_note: "Otter.ai (USA): ljudinspelningar och transkriptioner lagras på deras servrar. Inhämta informerat samtycke innan någon lektion spelas in. Gratisversionen lagrar inspelningar på obestämd tid; bekräfta lagringspolicyn. Spela inte in samtal med minderåriga utan uttryckligt tillstånd." },
    'quizlet': { desc: "Plattform för studiekort och lärandespel. AI-funktionen genererar automatiskt studieuppsättningar från anteckningar eller dokument. Effektivt för att befästa ordförråd och begrepp, särskilt för profiler med begränsat arbetsminne.", rgpd_note: "Quizlet Inc. (USA): användningsdata delas med tredje parter för reklamändamål i gratisversionen. För elever under 13 år krävs ett konto skapat av läraren (Quizlet Teacher). Plus- eller School-versionen tar bort reklam och förstärker integriteten." },
    'speechify': { desc: "Högkvalitativ text-till-tal-konverterare med naturliga röster på flera språk. Läser PDF-filer, webbsidor, dokument och e-post. Tillåter justering av läshastigheten och markerar texten när den läses upp. Användbart för elever med dyslexi eller dyspraxi.", rgpd_note: "Speechify Inc. (USA): inskickat innehåll bearbetas på deras servrar. Gratisversionen har en lyssnarmingränns; Premium är betald. För dokument med elevdata använd enbart anonyma kursstexter." },
  },

  da: {
    'chatgpt': { desc: "Sprogmodel til generel brug. Nyttigt til at tilpasse tekster, generere differentierede øvelser, skabe kontekstualiserede eksempler og udarbejde støttematerialer.", rgpd_note: "Den gratis version kan bruge samtaler til at træne modellen. Deaktiver under Indstillinger > Datakontroller. Send aldrig elevers navne, diagnoser eller identificerende oplysninger. Til institutionel brug overvej Teams- eller Enterprise-planen med en databehandleraftale." },
    'deepl': { desc: "Maskinoversættelse af høj kvalitet med fremragende resultater for europæiske sprog. Mere kontekstuelt præcis end Google Translate til akademiske tekster.", rgpd_note: "Den gratis version sender tekst til eksterne servere (DeepL GmbH, Tyskland, inden for EU). Pro-versionen inkluderer en GDPR-kompatibel databehandlingsaftale. Oversæt aldrig dokumenter med fulde navne eller følsomme elevoplysninger." },
    'diffit': { desc: "Genererer differentierede læsematerialer fra enhver tekst, URL eller emne. Tilpasser automatisk det sproglige kompleksitetsniveau med bibeholdelse af det faglige indhold. Nyttigt til at skabe versioner af samme tekst til forskellige elevprofiler.", rgpd_note: "Diffit (USA): indsendt indhold kan behandles af eksterne AI-modeller. Angiv ikke personlige elevoplysninger; brug kun med anonymt pensumsindhold." },
    'elsa-speak': { desc: "AI-udtaletrænere til engelsk. Analyserer brugerens tale og giver feedback fonem for fonem. Særligt nyttigt for elever der lærer engelsk som andetsprog og for lærere der identificerer udtalemønstre forbundet med elevens modersmål.", rgpd_note: "ELSA Corp. (USA): stemmeoptagelser behandles på deres servere. Gratisversionen har begrænsede funktioner; Pro er betalt. Tjek privatlivspolitikken for mindreårige og indhent forældrenes samtykke inden brug af stemmedata." },
    'grammarly': { desc: "AI-skriveassistent der retter grammatik, stavning og tegnsætning og foreslår forbedringer af tydelighed og tone. Tilgængelig som browserudvidelse og integreret i Google Docs og Word.", rgpd_note: "Grammarly Inc. (USA): data sendes til amerikanske servere. Gratisversionen kan bruge tekster til at forbedre modellen. Brug ikke tekster med identificerende oplysninger til følsomt elevindhold. Business-versionen inkluderer yderligere privatlivskontroller." },
    'immersive-reader': { desc: "Gratis immersiv læser integreret i Word, Teams, OneNote og Edge. Opdeler ord i stavelser, fremhæver ordklasser, læser tekst højt og justerer afstand og skriftstørrelse. Fungerer direkte i klassedokumenter.", rgpd_note: "Integreret i Microsofts produkter: databehandling følger Microsoft 365s privatlivspolitik. I skolemiljøer med Microsoft 365 Education-licens behandles elevdata som skoledata og bruges ikke til reklame." },
    'khanmigo': { desc: "Gratis læringsplatform med AI-tutor (Khanmigo). AI-tutoren tilpasser forklaringer til elevens tempo, stiller sokratiske spørgsmål i stedet for direkte svar og følger fremskridt. Særligt nyttigt for højt begavede elever og for elever med dansk som andetsprog.", rgpd_note: "Khan Academy (USA, nonprofit): data for mindreårige elever kræver en konto oprettet af en lærer eller værge. Khan Academy sælger ikke data til reklamebrug. Khanmigo har ekstra omkostninger for lærere; basisplatformen er gratis. Tjek GDPR-overensstemmelse til EU-brug." },
    'magicschool': { desc: "AI-platform designet specifikt til lærere. Inkluderer værktøjer til at differentiere lektionsplaner, skabe tilpasninger til elever med særlige behov, generere kommunikation til forældre og tilpasse materialer til forskellige læseniveauer.", rgpd_note: "MagicSchool AI (USA): platform designet til uddannelsesmæssig kontekst, COPPA/FERPA-kompatibel for amerikanske skoler. Tjek GDPR-overensstemmelse til EU-brug inden elevdata angives. Brug kun anonyme eller fiktive data indtil en databehandleraftale er bekræftet med skolen." },
    'natural-reader': { desc: "Konverterer skrevet tekst til syntetiseret tale. Nyttigt for elever med dysleksi eller dyspraksi, der drager fordel af auditiv støtte under læsning.", rgpd_note: "Gratisversionen er webbaseret. Indsend ikke tekster med personligt identificerbare elevoplysninger." },
    'notebooklm': { desc: "Googles værktøj der behandler dokumenter og giver mulighed for at stille spørgsmål, generere resuméer og oprette studieguider fra det uploadede materiale. Nyttigt til at tilpasse lange tekster.", rgpd_note: "Google-produkt. Data behandles i henhold til Google Workspace-vilkårene. Upload ikke dokumenter med personlige elevoplysninger. Brug kun med anonymt pensumsindhold." },
    'otter': { desc: "Automatisk lydtransskription i realtid. Nyttigt for elever med ADHD eller auditiv behandlingsvanskelighed til at følge mundtlige forklaringer og for lærere der opretter lektionstransskriptioner til gennemgang.", rgpd_note: "Otter.ai (USA): lydoptagelser og transskriptioner lagres på deres servere. Indhent informeret samtykke inden optagelse af en lektion. Gratisversionen opbevarer optagelser på ubestemt tid; bekræft opbevaringspolitikken. Optag ikke samtaler med mindreårige uden udtrykkelig tilladelse." },
    'quizlet': { desc: "Platform for flashcards og læringsopspil. AI-funktionen genererer automatisk studiesæt fra noter eller dokumenter. Effektivt til at konsolidere ordforråd og begreber, særligt for profiler med begrænset arbejdshukommelse.", rgpd_note: "Quizlet Inc. (USA): brugsdata deles med tredjeparter til reklamebrug i gratisversionen. For elever under 13 år kræves en konto oprettet af læreren (Quizlet Teacher). Plus- eller School-versionen fjerner reklamer og styrker privatlivet." },
    'speechify': { desc: "Højkvalitets tekst-til-tale-konverter med naturlige stemmer på flere sprog. Læser PDF-filer, websider, dokumenter og e-mails op. Giver mulighed for at justere læsehastighed og fremhæver tekst mens den læses op. Nyttigt for elever med dysleksi eller dyspraksi.", rgpd_note: "Speechify Inc. (USA): indsendt indhold behandles på deres servere. Gratisversionen har en grænse for lytteminutter; Premium er betalt. Brug kun anonyme kursustekster til dokumenter med elevdata." },
  },

  fi: {
    'chatgpt': { desc: "Yleiskäyttöinen kielimalli. Hyödyllinen tekstien mukauttamiseen, eriytettyjen harjoitusten luomiseen, kontekstualisoitujen esimerkkien kehittämiseen ja tukimateriaalien laatimiseen.", rgpd_note: "Maksuton versio voi käyttää keskusteluja mallin kouluttamiseen. Poista käytöstä kohdasta Asetukset > Tiedonhallinta. Älä koskaan lähetä oppilaiden nimiä, diagnooseja tai tunnistavia tietoja. Institutionaaliseen käyttöön harkitse Teams- tai Enterprise-suunnitelmaa tietojenkäsittelysopimuksella." },
    'deepl': { desc: "Korkealaatuinen konekäännös, joka soveltuu erityisesti eurooppalaisiin kieliin. Kontekstuaalisesti tarkempi kuin Google Kääntäjä akateemisille teksteille.", rgpd_note: "Maksuton versio lähettää tekstin ulkoisille palvelimille (DeepL GmbH, Saksa, EU:n sisällä). Pro-versio sisältää GDPR-yhteensopivan tietojenkäsittelysopimuksen. Älä koskaan käännä asiakirjoja, joissa on oppilaiden koko nimiä tai arkaluonteisia tietoja." },
    'diffit': { desc: "Luo eriytettyä lukumateriaalia mistä tahansa tekstistä, URL-osoitteesta tai aiheesta. Mukauttaa automaattisesti kielellistä monimutkaisuustasoa säilyttäen akateemisen sisällön. Hyödyllistä saman tekstin eri versioiden luomiseen eri oppilasprofiileille.", rgpd_note: "Diffit (USA): lähetettyä sisältöä voidaan käsitellä ulkoisilla tekoälymalleilla. Älä syötä oppilaiden henkilötietoja; käytä vain nimettömällä opetussuunnitelmamateriaalilla." },
    'elsa-speak': { desc: "Tekoälypohjainen englannin ääntämisharjoitteluohjelma. Analysoi käyttäjän puhetta ja antaa palautetta foneemi foneemilta. Erityisen hyödyllinen englantia toisena kielenä opiskeleville ja opettajille, jotka tunnistavat oppilaan äidinkieleen liittyviä ääntämismalleja.", rgpd_note: "ELSA Corp. (USA): ääninauhoituksia käsitellään heidän palvelimillaan. Maksuttomassa versiossa on rajoitetut toiminnot; Pro on maksullinen. Alaikäisten kohdalla tarkista tietosuojakäytäntö ja hanki vanhempien suostumus ennen äänitietojen käyttämistä." },
    'grammarly': { desc: "Tekoälykirjoitusavustaja, joka korjaa kieliopin, oikeinkirjoituksen ja välimerkit sekä ehdottaa parannuksia selkeyteen ja sävyyn. Saatavana selainlaajennuksena ja integroituna Google Docsiin ja Wordiin.", rgpd_note: "Grammarly Inc. (USA): tiedot lähetetään yhdysvaltalaisille palvelimille. Maksuton versio voi käyttää tekstejä mallin parantamiseen. Älä käytä tunnistavia tietoja sisältäviä tekstejä arkaluonteisessa oppilassisällössä. Business-versio sisältää lisää tietosuojaohjausta." },
    'immersive-reader': { desc: "Maksuton immersiivinen lukija integroituna Wordiin, Teamsiin, OneNoteen ja Edgeen. Jakaa sanat tavuihin, korostaa sanaluokkia, lukee tekstin ääneen ja säätää riviväliä ja fonttikokoa. Toimii suoraan luokkahuonedokumenteissa.", rgpd_note: "Integroitu Microsoftin tuotteisiin: tietojenkäsittely noudattaa Microsoft 365:n tietosuojakäytäntöä. Kouluympäristöissä, joissa on Microsoft 365 Education -lisenssi, oppilaiden tiedot käsitellään koulutietoina eikä niitä käytetä mainontaan." },
    'khanmigo': { desc: "Maksuton oppimisalusta tekoälytutorin kanssa (Khanmigo). Tekoälytutor mukauttaa selitykset oppilaan tempoon, esittää sokraattisia kysymyksiä suorien vastausten sijaan ja seuraa edistymistä. Erityisen hyödyllinen lahjakkailla oppilailla ja suomea toisena kielenä opiskeleville.", rgpd_note: "Khan Academy (USA, voittoa tavoittelematon): alaikäisten oppilaiden tiedot vaativat opettajan tai huoltajan luoman tilin. Khan Academy ei myy tietoja mainostarkoituksiin. Khanmigo maksaa opettajille lisää; perusalusta on maksuton. Tarkista GDPR-yhteensopivuus EU-käyttöön." },
    'magicschool': { desc: "Tekoälyalusta suunniteltu erityisesti opettajille. Sisältää työkaluja tuntisuunnitelmien eriyttämiseen, mukautusten luomiseen oppilaille, joilla on erityisopetuksen tarvetta, viestintöjen tuottamiseen vanhemmille ja materiaalien mukauttamiseen eri lukutasoille.", rgpd_note: "MagicSchool AI (USA): oppimisympäristöön suunniteltu alusta, COPPA/FERPA-yhteensopiva yhdysvaltalaisille kouluille. EU-käyttöön tarkista GDPR-yhteensopivuus ennen oppilaiden tietojen syöttämistä. Käytä vain nimettömiä tai kuvitteellisia tietoja, kunnes koulun tietojenkäsittelysopimus on vahvistettu." },
    'natural-reader': { desc: "Muuntaa kirjoitetun tekstin syntetisoituun puheeksi. Hyödyllinen oppilaille, joilla on lukihäiriö tai dyspraksia, jotka hyötyvät auditiivisesta tuesta lukemisen aikana.", rgpd_note: "Maksuton versio on verkkopohjainen. Älä lähetä tekstejä, joissa on henkilökohtaisesti tunnistettavia oppilastietoja." },
    'notebooklm': { desc: "Googlen työkalu, joka käsittelee asiakirjoja ja mahdollistaa kysymysten esittämisen, yhteenvetojen luomisen ja opaskirjojen tekemisen ladatusta materiaalista. Hyödyllinen pitkien tekstien mukauttamiseen.", rgpd_note: "Google-tuote. Tiedot käsitellään Google Workspace -ehtojen mukaisesti. Älä lataa asiakirjoja, joissa on oppilaiden henkilötietoja. Käytä vain nimettömällä opetussuunnitelmamateriaalilla." },
    'otter': { desc: "Automaattinen äänen transkriptio reaaliajassa. Hyödyllistä ADHD-oppilaille tai kuulonkäsittelyvaikeuksista kärsiville suullisten selitysten seuraamiseen sekä opettajille, jotka luovat kertausta varten tuntitransskriptioita.", rgpd_note: "Otter.ai (USA): ääninauhoitukset ja transkriptiot tallennetaan heidän palvelimilleen. Hanki tietoinen suostumus ennen minkään tunnin nauhoittamista. Maksuton versio tallentaa nauhoituksia toistaiseksi; vahvista säilytyskäytäntö. Älä nauhoita alaikäisten kanssa käytyjä keskusteluja ilman nimenomaista lupaa." },
    'quizlet': { desc: "Muistikortti- ja oppimispelialusta. Tekoälytoiminto luo automaattisesti opiskelusarjoja muistiinpanoista tai asiakirjoista. Tehokas sanavaraston ja käsitteiden vahvistamiseen, erityisesti oppilaille, joilla on rajoittunut työmuisti.", rgpd_note: "Quizlet Inc. (USA): käyttötiedot jaetaan kolmansille osapuolille mainontaa varten maksuttomassa versiossa. Alle 13-vuotiaille oppilaille tarvitaan opettajan luoma tili (Quizlet Teacher). Plus- tai School-versio poistaa mainokset ja vahvistaa tietosuojaa." },
    'speechify': { desc: "Korkealaatuinen tekstistä puheeksi -muunnin luonnollisilla äänillä useilla kielillä. Lukee PDF-tiedostoja, verkkosivuja, asiakirjoja ja sähköposteja. Mahdollistaa lukemisnopeuden säätämisen ja korostaa tekstin lukemisen edetessä. Hyödyllinen lukihäiriö- tai dyspraksiaoppilaille.", rgpd_note: "Speechify Inc. (USA): lähetettyä sisältöä käsitellään heidän palvelimillaan. Maksuttomassa versiossa on kuunteluminuttirajat; Premium on maksullinen. Asiakirjoille, joissa on oppilastietoja, käytä vain nimettömiä opetussuunnitelmatekstejä." },
  },

  sk: {
    'chatgpt': { desc: "Jazykový model na všeobecné použitie. Vhodný na prispôsobenie textov, vytváranie diferencovaných cvičení, tvorbu kontextualizovaných príkladov a prípravu podporných materiálov.", rgpd_note: "Bezplatná verzia môže využívať konverzácie na trénovanie modelu. Deaktivovať v Nastaveniach > Ovládanie dát. Nikdy nezasielať mená, diagnózy ani identifikujúce údaje žiakov. Na inštitucionálne použitie zvážiť plán Teams alebo Enterprise so zmluvou o spracovaní údajov." },
    'deepl': { desc: "Vysokokvalitný strojový preklad s výbornými výsledkami pre európske jazyky. Kontextovo presnejší ako Google Prekladač pre akademické texty.", rgpd_note: "Bezplatná verzia odosiela text na externé servery (DeepL GmbH, Nemecko, v EÚ). Verzia Pro zahŕňa zmluvu o spracovaní údajov v súlade s GDPR. Nikdy neprekladať dokumenty s celými menami alebo citlivými údajmi žiakov." },
    'diffit': { desc: "Generuje diferencované čitateľské materiály z akéhokoľvek textu, URL alebo témy. Automaticky prispôsobuje úroveň jazykovej náročnosti pri zachovaní akademického obsahu. Vhodné na tvorbu rôznych verzií toho istého textu pre rôzne profily žiakov.", rgpd_note: "Diffit (USA): odoslaný obsah môže byť spracovaný externými modelmi AI. Nezadávať osobné údaje žiakov; používať len s anonymným kurikulárnym obsahom." },
    'elsa-speak': { desc: "Tréner výslovnosti angličtiny s AI. Analyzuje reč používateľa a poskytuje spätnú väzbu foném po fonéme. Zvlášť užitočné pre žiakov učiacich sa angličtinu ako J2 a pre učiteľov identifikujúcich vzorce výslovnosti spojené s materinským jazykom žiaka.", rgpd_note: "ELSA Corp. (USA): hlasové nahrávky spracovávané na ich serveroch. Bezplatná verzia má obmedzené funkcie; Pro je platená. U maloletých skontrolovať zásady ochrany osobných údajov a pred použitím hlasových dát získať súhlas rodičov." },
    'grammarly': { desc: "Asistent písania s AI opravujúci gramatiku, pravopis a interpunkciu a navrhujúci zlepšenia zrozumiteľnosti a tónu. Dostupný ako rozšírenie prehliadača a integrovaný do Google Docs a Wordu.", rgpd_note: "Grammarly Inc. (USA): dáta odosielané na americké servery. Bezplatná verzia môže texty využívať na zlepšenie modelu. Pri citlivom obsahu žiakov nepoužívať texty s identifikujúcimi údajmi. Verzia Business obsahuje ďalšie ovládanie ochrany súkromia." },
    'immersive-reader': { desc: "Bezplatný imerzívny čítač integrovaný vo Worde, Teams, OneNote a Edge. Delí slová na slabiky, zvýrazňuje slovné druhy, číta text nahlas a upravuje medzery a veľkosť písma. Funguje priamo v triednych dokumentoch.", rgpd_note: "Integrovaný do produktov Microsoft: spracovanie dát sa riadi zásadami ochrany osobných údajov Microsoft 365. V školskom prostredí s licenciou Microsoft 365 Education sú dáta žiakov spracovávané ako školské dáta a nie sú využívané na reklamné účely." },
    'khanmigo': { desc: "Bezplatná vzdelávacia platforma s AI tútorom (Khanmigo). AI tútor prispôsobuje vysvetlenia tempu žiaka, kladie sokratovské otázky namiesto priamych odpovedí a sleduje pokrok. Zvlášť vhodné pre nadaných žiakov a pre žiakov so slovenčinou ako J2.", rgpd_note: "Khan Academy (USA, nezisková organizácia): dáta maloletých žiakov vyžadujú účet vytvorený učiteľom alebo zákonným zástupcom. Khan Academy nepredáva dáta na reklamné účely. Khanmigo má pre učiteľov príplatok; základná platforma je zadarmo. Overiť súlad s GDPR na použitie v EÚ." },
    'magicschool': { desc: "AI platforma navrhnutá špeciálne pre učiteľov. Obsahuje nástroje na diferenciáciu výukových plánov, tvorbu adaptácií pre žiakov so špeciálnymi výchovno-vzdelávacími potrebami, generovanie komunikácie pre rodičov a prispôsobenie materiálov rôznym úrovniam čítania.", rgpd_note: "MagicSchool AI (USA): platforma určená pre vzdelávací kontext, v súlade s COPPA/FERPA pre americké školy. Na použitie v EÚ overiť súlad s GDPR pred zadávaním dát žiakov. Používať len anonymné alebo fiktívne dáta do potvrdenia zmluvy o spracovaní dát so školou." },
    'natural-reader': { desc: "Prevádza písaný text na syntetizovaný hlas. Vhodné pre žiakov s dyslexiou alebo dyspraxiou, ktorí profitujú zo zvukovej podpory pri čítaní.", rgpd_note: "Bezplatná verzia je webová aplikácia. Nezasielať texty s osobne identifikovateľnými údajmi žiakov." },
    'notebooklm': { desc: "Nástroj Google, ktorý spracováva dokumenty a umožňuje klásť otázky, generovať zhrnutia a vytvárať študijné príručky z nahratého materiálu. Vhodné na prispôsobenie dlhých textov.", rgpd_note: "Produkt Google. Dáta spracovávané podľa podmienok Google Workspace. Nenahrávať dokumenty s osobnými údajmi žiakov. Používať len s anonymnými kurikulárnymi materiálmi." },
    'otter': { desc: "Automatický prepis zvuku v reálnom čase. Vhodné pre žiakov s ADHD alebo ťažkosťami so sluchovým spracovaním pri sledovaní ústneho výkladu a pre učiteľov vytvárajúcich záznamy hodín na opakovanie.", rgpd_note: "Otter.ai (USA): zvukové nahrávky a prepisy uložené na ich serveroch. Pred nahrávaním akejkoľvek hodiny získať informovaný súhlas. Bezplatná verzia uchováva nahrávky na dobu neurčitú; potvrdiť zásady uchovávania. Nenahrávať rozhovory s maloletými bez výslovného súhlasu." },
    'quizlet': { desc: "Platforma pre študijné kartičky a vzdelávacie hry. Funkcia AI automaticky generuje študijné sady z poznámok alebo dokumentov. Efektívne na upevňovanie slovnej zásoby a pojmov, zvlášť pre profily s obmedzenou pracovnou pamäťou.", rgpd_note: "Quizlet Inc. (USA): dáta o využívaní zdieľané s tretími stranami na reklamné účely v bezplatnej verzii. Pre žiakov mladších ako 13 rokov je potrebný účet vytvorený učiteľom (Quizlet Teacher). Verzia Plus alebo School odstraňuje reklamy a posiluje ochranu súkromia." },
    'speechify': { desc: "Vysokokvalitný konvertor textu na reč s prirodzenými hlasmi v niekoľkých jazykoch. Číta PDF súbory, webové stránky, dokumenty a e-maily. Umožňuje nastaviť rýchlosť čítania a zvýrazňuje text pri čítaní. Vhodné pre žiakov s dyslexiou alebo dyspraxiou.", rgpd_note: "Speechify Inc. (USA): odoslaný obsah spracovávaný na ich serveroch. Bezplatná verzia má limit poslechových minút; Premium je platená. Pre dokumenty s dátami žiakov používať len anonymné výukové texty." },
  },

  el: {
    'chatgpt': { desc: "Γλωσσικό μοντέλο γενικής χρήσης. Χρήσιμο για προσαρμογή κειμένων, δημιουργία διαφοροποιημένων ασκήσεων, ανάπτυξη παραδειγμάτων και σύνταξη υποστηρικτικού υλικού.", rgpd_note: "Η δωρεάν έκδοση μπορεί να χρησιμοποιεί συνομιλίες για εκπαίδευση του μοντέλου. Απενεργοποιήστε στις Ρυθμίσεις > Έλεγχος δεδομένων. Μην αποστέλλετε ποτέ ονόματα μαθητών, διαγνώσεις ή αναγνωριστικά στοιχεία. Για θεσμική χρήση, εξετάστε το πλάνο Teams ή Enterprise με Σύμβαση Επεξεργασίας Δεδομένων." },
    'deepl': { desc: "Υψηλής ποιότητας αυτόματη μετάφραση με εξαιρετικά αποτελέσματα για ευρωπαϊκές γλώσσες. Πιο κατάλληλη συμφραστικά από το Google Translate για ακαδημαϊκά κείμενα.", rgpd_note: "Η δωρεάν έκδοση αποστέλλει κείμενο σε εξωτερικούς διακομιστές (DeepL GmbH, Γερμανία, εντός ΕΕ). Η έκδοση Pro περιλαμβάνει σύμβαση επεξεργασίας δεδομένων συμβατή με τον GDPR. Μην μεταφράζετε ποτέ έγγραφα με πλήρη ονόματα ή ευαίσθητα δεδομένα μαθητών." },
    'diffit': { desc: "Δημιουργεί διαφοροποιημένο αναγνωστικό υλικό από οποιοδήποτε κείμενο, URL ή θέμα. Προσαρμόζει αυτόματα το γλωσσικό επίπεδο πολυπλοκότητας διατηρώντας το ακαδημαϊκό περιεχόμενο. Χρήσιμο για τη δημιουργία εκδόσεων ενός κειμένου για διαφορετικά προφίλ μαθητών.", rgpd_note: "Diffit (ΗΠΑ): το περιεχόμενο που υποβάλλεται ενδέχεται να επεξεργαστεί από εξωτερικά μοντέλα ΤΝ. Μην εισάγετε προσωπικά δεδομένα μαθητών. Χρησιμοποιήστε μόνο με ανώνυμο εκπαιδευτικό υλικό." },
    'elsa-speak': { desc: "Εκπαιδευτής προφοράς αγγλικών με ΤΝ. Αναλύει την ομιλία του χρήστη και παρέχει ανατροφοδότηση ανά φώνημα. Ιδιαίτερα χρήσιμο για μαθητές που μαθαίνουν αγγλικά ως Γ2 και για εκπαιδευτικούς που εντοπίζουν σχέδια προφοράς που συνδέονται με τη μητρική γλώσσα.", rgpd_note: "ELSA Corp. (ΗΠΑ): οι ηχογραφήσεις φωνής επεξεργάζονται στους διακομιστές τους. Η δωρεάν έκδοση έχει περιορισμένες λειτουργίες. Για ανηλίκους, ελέγξτε την πολιτική απορρήτου και λάβετε γονική συγκατάθεση πριν χρησιμοποιήσετε φωνητικά δεδομένα." },
    'grammarly': { desc: "Βοηθός γραφής με ΤΝ που διορθώνει γραμματική, ορθογραφία και σημεία στίξης και προτείνει βελτιώσεις σαφήνειας και τόνου. Διαθέσιμο ως επέκταση προγράμματος περιήγησης και ενσωματωμένο στο Google Docs και το Word.", rgpd_note: "Grammarly Inc. (ΗΠΑ): τα δεδομένα αποστέλλονται σε αμερικανικούς διακομιστές. Η δωρεάν έκδοση μπορεί να χρησιμοποιεί κείμενα για βελτίωση του μοντέλου. Για ευαίσθητο περιεχόμενο μαθητών, μην χρησιμοποιείτε κείμενα με αναγνωριστικά δεδομένα. Η έκδοση Business παρέχει πρόσθετους ελέγχους απορρήτου." },
    'immersive-reader': { desc: "Δωρεάν καθηλωτικός αναγνώστης ενσωματωμένος στο Word, Teams, OneNote και Edge. Χωρίζει λέξεις σε συλλαβές, επισημαίνει μέρη του λόγου, διαβάζει κείμενο φωναχτά και ρυθμίζει απόσταση και μέγεθος γραμματοσειράς. Λειτουργεί απευθείας στα έγγραφα της τάξης.", rgpd_note: "Ενσωματωμένο στα προϊόντα Microsoft: η επεξεργασία δεδομένων ακολουθεί την πολιτική απορρήτου Microsoft 365. Σε σχολικά περιβάλλοντα με άδεια Microsoft 365 Education, τα δεδομένα μαθητών αντιμετωπίζονται ως σχολικά δεδομένα και δεν χρησιμοποιούνται για διαφήμιση." },
    'khanmigo': { desc: "Δωρεάν πλατφόρμα μάθησης με ΤΝ εκπαιδευτή (Khanmigo). Ο εκπαιδευτής ΤΝ προσαρμόζει τις εξηγήσεις στον ρυθμό του μαθητή, κάνει σωκρατικές ερωτήσεις αντί για άμεσες απαντήσεις και παρακολουθεί την πρόοδο. Ιδιαίτερα χρήσιμο για ταλαντούχους μαθητές και για εκείνους που μαθαίνουν ελληνικά ως Γ2.", rgpd_note: "Khan Academy (ΗΠΑ, μη κερδοσκοπική): τα δεδομένα ανηλίκων μαθητών απαιτούν λογαριασμό που δημιουργήθηκε από εκπαιδευτικό ή κηδεμόνα. Η Khan Academy δεν πωλεί δεδομένα για διαφήμιση. Ελέγξτε τη συμμόρφωση με τον GDPR για χρήση στην ΕΕ." },
    'magicschool': { desc: "Πλατφόρμα ΤΝ σχεδιασμένη αποκλειστικά για εκπαιδευτικούς. Περιλαμβάνει εργαλεία για διαφοροποίηση σχεδίων μαθήματος, δημιουργία προσαρμογών για μαθητές με ΕΕΑ, παραγωγή επικοινωνίας για γονείς και προσαρμογή υλικού σε διαφορετικά επίπεδα ανάγνωσης.", rgpd_note: "MagicSchool AI (ΗΠΑ): πλατφόρμα σχεδιασμένη για εκπαιδευτικό πλαίσιο, συμβατή με COPPA/FERPA για αμερικανικά σχολεία. Για χρήση στην ΕΕ, επαληθεύστε τη συμμόρφωση με τον GDPR πριν εισάγετε δεδομένα μαθητών. Χρησιμοποιήστε μόνο ανώνυμα ή φανταστικά δεδομένα έως ότου επιβεβαιωθεί σύμβαση επεξεργασίας δεδομένων με το σχολείο." },
    'natural-reader': { desc: "Μετατρέπει γραπτό κείμενο σε συντεθειμένη φωνή. Χρήσιμο για μαθητές με δυσλεξία ή δυσπραξία που επωφελούνται από ηχητική υποστήριξη κατά την ανάγνωση.", rgpd_note: "Η δωρεάν έκδοση είναι διαδικτυακή. Μην υποβάλλετε κείμενα με προσωπικά αναγνωρίσιμα δεδομένα μαθητών." },
    'notebooklm': { desc: "Εργαλείο Google που επεξεργάζεται έγγραφα και επιτρέπει ερωτήσεις, δημιουργία περιλήψεων και οδηγών μελέτης από το υλικό που ανεβάστηκε. Χρήσιμο για προσαρμογή μεγάλων κειμένων.", rgpd_note: "Προϊόν Google. Τα δεδομένα επεξεργάζονται σύμφωνα με τους όρους του Google Workspace. Μην ανεβάζετε έγγραφα με προσωπικά δεδομένα μαθητών. Χρησιμοποιήστε μόνο με ανώνυμο εκπαιδευτικό υλικό." },
    'otter': { desc: "Αυτόματη μεταγραφή ήχου σε πραγματικό χρόνο. Χρήσιμο για μαθητές με ΔΕΠΥ ή δυσκολίες ακουστικής επεξεργασίας για να παρακολουθούν προφορικές εξηγήσεις, και για εκπαιδευτικούς που δημιουργούν μεταγραφές μαθημάτων.", rgpd_note: "Otter.ai (ΗΠΑ): οι ηχογραφήσεις και μεταγραφές αποθηκεύονται στους διακομιστές τους. Λάβετε ενημερωμένη συγκατάθεση πριν ηχογραφήσετε οποιοδήποτε μάθημα. Η δωρεάν έκδοση αποθηκεύει ηχογραφήσεις επ' αόριστον. Μην ηχογραφείτε συνομιλίες με ανηλίκους χωρίς ρητή άδεια." },
    'quizlet': { desc: "Πλατφόρμα καρτελών μελέτης και εκπαιδευτικών παιχνιδιών. Η λειτουργία ΤΝ δημιουργεί αυτόματα σετ μελέτης από σημειώσεις ή έγγραφα. Αποτελεσματικό για εδραίωση λεξιλογίου και εννοιών, ιδιαίτερα για μαθητές με περιορισμένη εργαζόμενη μνήμη.", rgpd_note: "Quizlet Inc. (ΗΠΑ): τα δεδομένα χρήσης κοινοποιούνται σε τρίτους για διαφήμιση στη δωρεάν έκδοση. Για μαθητές κάτω των 13 ετών απαιτείται λογαριασμός που δημιούργησε ο εκπαιδευτικός (Quizlet Teacher). Η έκδοση Plus ή School αφαιρεί τις διαφημίσεις και ενισχύει την προστασία του απορρήτου." },
    'speechify': { desc: "Μετατροπέας κειμένου σε ομιλία υψηλής ποιότητας με φυσικές φωνές σε πολλές γλώσσες. Διαβάζει αρχεία PDF, ιστοσελίδες, έγγραφα και email. Επιτρέπει ρύθμιση ταχύτητας ανάγνωσης και επισημαίνει το κείμενο κατά την ανάγνωση. Χρήσιμο για μαθητές με δυσλεξία ή δυσπραξία.", rgpd_note: "Speechify Inc. (ΗΠΑ): το υποβαλλόμενο περιεχόμενο επεξεργάζεται στους διακομιστές τους. Η δωρεάν έκδοση έχει όριο λεπτών ακρόασης. Για έγγραφα με δεδομένα μαθητών, χρησιμοποιήστε μόνο ανώνυμα εκπαιδευτικά κείμενα." },
  },

  hu: {
    'chatgpt': { desc: "Általános célú nyelvi modell. Hasznos szövegek adaptálásához, differenciált feladatok generálásához, kontextualizált példák létrehozásához és támogató anyagok elkészítéséhez.", rgpd_note: "Az ingyenes verzió a modell betanításához felhasználhatja a beszélgetéseket. Tiltsa le a Beállítások > Adatvezérlők menüpontban. Soha ne küldjön tanulók nevét, diagnózisát vagy azonosító adatait. Intézményi felhasználáshoz fontolja meg a Teams vagy Enterprise tervet adatfeldolgozási megállapodással." },
    'deepl': { desc: "Kiváló minőségű gépi fordítás, kiemelkedő eredményekkel európai nyelveken. Az akadémiai szövegek esetén kontextuálisan pontosabb, mint a Google Fordító.", rgpd_note: "Az ingyenes verzió szöveget küld külső szerverekre (DeepL GmbH, Németország, az EU-n belül). A Pro verzió GDPR-kompatibilis adatfeldolgozási szerződést tartalmaz. Soha ne fordítson teljes neveket vagy érzékeny tanulói adatokat tartalmazó dokumentumokat." },
    'diffit': { desc: "Differenciált olvasmányanyagokat hoz létre bármely szövegből, URL-ből vagy témából. Automatikusan igazítja a nyelvi bonyolultsági szintet az akadémiai tartalom megőrzése mellett. Hasznos ugyanazon szöveg különböző verziói létrehozásához különböző tanulói profilok számára.", rgpd_note: "Diffit (USA): a beküldött tartalmakat külső MI-modellek dolgozhatják fel. Ne adjon meg személyes tanulói adatokat; csak névtelen tantervi tartalommal használja." },
    'elsa-speak': { desc: "MI-alapú angol kiejtés-tréner. Elemzi a felhasználó beszédét, és foném-szintű visszajelzést ad. Különösen hasznos a másodnyelvként angolt tanuló diákok és az anyanyelvhez kapcsolódó kiejtési mintákat azonosító tanárok számára.", rgpd_note: "ELSA Corp. (USA): a hangfelvételeket a szervereiken dolgozzák fel. Az ingyenes verzió korlátozott funkciókkal rendelkezik; a Pro fizetős. Kiskorúak esetén ellenőrizze az adatvédelmi szabályzatot, és szerezzen szülői beleegyezést a hangadatok felhasználása előtt." },
    'grammarly': { desc: "MI írástámogató, amely javítja a grammatikát, helyesírást és írásjeleket, valamint egyértelműségi és hangnemi fejlesztéseket javasol. Böngészőbővítményként érhető el, és be van építve a Google Docsba és a Wordbe.", rgpd_note: "Grammarly Inc. (USA): az adatokat USA-beli szerverekre küldik. Az ingyenes verzió a modell fejlesztéséhez szövegeket használhat. Érzékeny tanulói tartalmak esetén ne használjon azonosító adatokat tartalmazó szövegeket. A Business verzió további adatvédelmi vezérlőket tartalmaz." },
    'immersive-reader': { desc: "Ingyenes, a Word, Teams, OneNote és Edge alkalmazásba integrált közvetlen olvasó. Szótagokra bontja a szavakat, kiemeli a szófajokat, hangosan olvassa a szöveget, és beállítja a betűközöket és betűméretet. Közvetlenül az osztálytermi dokumentumokban működik.", rgpd_note: "Microsoft-termékekbe integrálva: az adatkezelés a Microsoft 365 adatvédelmi szabályzatát követi. Microsoft 365 Education licenccel rendelkező iskolai környezetben a tanulói adatokat iskolai adatként kezelik, és nem használják reklámozásra." },
    'khanmigo': { desc: "Ingyenes tanulási platform MI-tutorral (Khanmigo). A MI-tutor az egyes tanulók tempójához igazítja a magyarázatokat, szókratikus kérdéseket tesz fel közvetlen válaszok helyett, és nyomon követi az előrehaladást. Különösen hasznos a tehetséges tanulók és a magyart második nyelvként tanulók számára.", rgpd_note: "Khan Academy (USA, nonprofit): a kiskorú tanulók adataihoz tanár vagy gyám által létrehozott fiókra van szükség. A Khan Academy nem értékesíti az adatokat reklámozás céljából. A Khanmigo tanároknak extra díjat számít fel; az alapplatform ingyenes. EU-beli felhasználáshoz ellenőrizze a GDPR-megfelelőséget." },
    'magicschool': { desc: "Kifejezetten tanároknak tervezett MI-platform. Tartalmaz eszközöket a tanmenetek differenciálásához, az SNI-s tanulók számára szükséges módosítások létrehozásához, a szülőkkel való kommunikáció generálásához és az anyagok különböző olvasási szintekhez való igazításához.", rgpd_note: "MagicSchool AI (USA): oktatási kontextusra tervezett platform, COPPA/FERPA-kompatibilis az USA-beli iskolák számára. Az EU-beli felhasználáshoz ellenőrizze a GDPR-megfelelőséget a tanulói adatok megadása előtt. Csak névtelen vagy fiktív adatokat használjon, amíg az iskolával kötött adatfeldolgozási megállapodás meg nem születik." },
    'natural-reader': { desc: "Írott szöveget szintetizált hangzá alakít. Hasznos a diszlexiás vagy diszpraxiás tanulók számára, akik olvasás közben auditív támogatásból részesülnek.", rgpd_note: "Az ingyenes verzió webalapú. Ne küldjön személyesen azonosítható tanulói adatokat tartalmazó szövegeket." },
    'notebooklm': { desc: "Google eszköz, amely dokumentumokat dolgoz fel, és lehetővé teszi kérdések feltevését, összefoglalók generálását és tanulmányi útmutatók készítését a feltöltött anyagból. Hasznos hosszú szövegek adaptálásához.", rgpd_note: "Google-termék. Az adatokat a Google Workspace feltételei szerint dolgozzák fel. Ne töltsön fel személyes tanulói adatokat tartalmazó dokumentumokat. Csak névtelen tantervi anyagokkal használja." },
    'otter': { desc: "Valós idejű automatikus hangátírás. Hasznos az ADHD-s vagy hallási feldolgozási nehézségekkel küzdő tanulók számára a szóbeli magyarázatok követéséhez, és a tanárok számára, akik átismétlésre szánt óraátiratokat készítenek.", rgpd_note: "Otter.ai (USA): a hangfelvételeket és átiratokat a szervereiken tárolják. Az óra rögzítése előtt szerezzen tájékozott hozzájárulást. Az ingyenes verzió határozatlan ideig tárolja a felvételeket; erősítse meg az adatmegőrzési szabályzatot. Kiskorúakkal folytatott beszélgetéseket ne rögzítsen kifejezett engedély nélkül." },
    'quizlet': { desc: "Tanulókártyás és oktatójátékos platform. A MI-funkció automatikusan tanulási készleteket generál jegyzetek vagy dokumentumok alapján. Hatékony a szókincs és fogalmak megszilárdításához, különösen a korlátozott munkamemóriájú tanulói profilok esetén.", rgpd_note: "Quizlet Inc. (USA): az ingyenes verzióban a felhasználási adatokat harmadik felekkel osztják meg reklámozás céljából. A 13 évesnél fiatalabb tanulókhoz tanár által létrehozott fiókra van szükség (Quizlet Teacher). A Plus vagy School verzió eltávolítja a hirdetéseket és megerősíti az adatvédelmet." },
    'speechify': { desc: "Kiváló minőségű szöveg-hangzóvá-alakító természetes hangokkal több nyelven. Felolvassa a PDF-fájlokat, weboldalakat, dokumentumokat és e-maileket. Lehetővé teszi az olvasási sebesség beállítását, és olvasás közben kiemeli a szöveget. Hasznos a diszlexiás vagy diszpraxiás tanulók számára.", rgpd_note: "Speechify Inc. (USA): a beküldött tartalmakat a szervereiken dolgozzák fel. Az ingyenes verzióban hallgatási perckorlát van; a Premium fizetős. Tanulói adatokat tartalmazó dokumentumokhoz csak névtelen tantervi szövegeket használjon." },
  },

  bg: {
    'chatgpt': { desc: "Езиков модел с общо предназначение. Полезен за адаптиране на текстове, генериране на диференцирани упражнения, създаване на контекстуализирани примери и изготвяне на учебни материали.", rgpd_note: "Безплатната версия може да използва разговорите за обучение на модела. Деактивирайте в Настройки > Контрол на данните. Никога не изпращайте имена на ученици, диагнози или идентифициращи данни. За институционална употреба разгледайте плана Teams или Enterprise с договор за обработка на данни." },
    'deepl': { desc: "Висококачествен машинен превод с отлични резултати за европейски езици. Контекстуално по-точен от Google Translate за академични текстове.", rgpd_note: "Безплатната версия изпраща текст към външни сървъри (DeepL GmbH, Германия, в ЕС). Версията Pro включва договор за обработка на данни, съответстващ на GDPR. Никога не превеждайте документи с пълни имена или чувствителни данни на ученици." },
    'diffit': { desc: "Генерира диференцирани материали за четене от всеки текст, URL или тема. Автоматично адаптира нивото на езикова сложност, запазвайки академичното съдържание. Полезно за създаване на различни версии на един текст за различни профили ученици.", rgpd_note: "Diffit (САЩ): изпратеното съдържание може да бъде обработено от външни AI модели. Не въвеждайте лични данни на ученици; използвайте само с анонимно учебно съдържание." },
    'elsa-speak': { desc: "AI треньор за произношение на английски. Анализира речта на потребителя и дава обратна връзка фонема по фонема. Особено полезен за учещи английски като Л2 и за учители, идентифициращи модели на произношение, свързани с майчиния език на ученика.", rgpd_note: "ELSA Corp. (САЩ): гласовите записи се обработват на техните сървъри. Безплатната версия има ограничени функции; Pro е платена. За непълнолетни проверете политиката за поверителност и получете родителско съгласие преди използване на гласови данни." },
    'grammarly': { desc: "AI асистент за писане, който коригира граматика, правопис и пунктуация и предлага подобрения в яснотата и тона. Достъпен като разширение за браузъра и интегриран в Google Docs и Word.", rgpd_note: "Grammarly Inc. (САЩ): данните се изпращат към американски сървъри. Безплатната версия може да използва текстове за подобряване на модела. За чувствително съдържание не използвайте текстове с идентифициращи данни. Версията Business включва допълнителни контроли за поверителност." },
    'immersive-reader': { desc: "Безплатен имерсивен четец, интегриран в Word, Teams, OneNote и Edge. Разделя думите на срички, подчертава части на речта, чете текста на глас и регулира разстоянието и размера на шрифта. Работи директно в класните документи.", rgpd_note: "Интегриран в продуктите на Microsoft: обработката на данни следва политиката за поверителност на Microsoft 365. В учебна среда с лицензия Microsoft 365 Education данните на учениците се третират като учебни данни и не се използват за реклама." },
    'khanmigo': { desc: "Безплатна учебна платформа с AI ментор (Khanmigo). AI менторът адаптира обясненията към темпото на ученика, задава сократови въпроси вместо директни отговори и проследява напредъка. Особено полезен за надарени ученици и за учещи български като Л2.", rgpd_note: "Khan Academy (САЩ, организация с нестопанска цел): данните на непълнолетни ученици изискват акаунт, създаден от учител или настойник. Khan Academy не продава данни за реклама. Khanmigo има допълнителна такса за учители; основната платформа е безплатна. Проверете спазването на GDPR за употреба в ЕС." },
    'magicschool': { desc: "AI платформа, проектирана специално за учители. Включва инструменти за диференциране на учебни планове, създаване на адаптации за ученици с образователни потребности, генериране на комуникации за родители и адаптиране на материали към различни нива на четене.", rgpd_note: "MagicSchool AI (САЩ): платформа, проектирана за образователен контекст, в съответствие с COPPA/FERPA за американски училища. За употреба в ЕС проверете спазването на GDPR преди въвеждане на ученически данни. Използвайте само анонимни или измислени данни до потвърждаване на договор за обработка на данни с училището." },
    'natural-reader': { desc: "Конвертира писмен текст в синтезирана реч. Полезен за ученици с дислексия или диспраксия, които се възползват от слухова подкрепа при четене.", rgpd_note: "Безплатната версия е уеб базирана. Не изпращайте текстове с лично идентифицируеми данни на ученици." },
    'notebooklm': { desc: "Инструмент на Google, който обработва документи и позволява задаване на въпроси, генериране на резюмета и създаване на учебни ръководства от качения материал. Полезен за адаптиране на дълги текстове.", rgpd_note: "Продукт на Google. Данните се обработват съгласно условията на Google Workspace. Не качвайте документи с лични данни на ученици. Използвайте само с анонимни учебни материали." },
    'otter': { desc: "Автоматична транскрипция на аудио в реално време. Полезен за ученици с ADHD или затруднения в слуховата обработка за следване на устни обяснения и за учители, създаващи транскрипти на уроци за преговор.", rgpd_note: "Otter.ai (САЩ): аудио записите и транскриптите се съхраняват на техните сървъри. Получете информирано съгласие преди записване на урок. Безплатната версия съхранява записите неограничено; потвърдете политиката за задържане. Не записвайте разговори с непълнолетни без изрично разрешение." },
    'quizlet': { desc: "Платформа за флашкарти и учебни игри. Функцията AI автоматично генерира учебни набори от бележки или документи. Ефективна за затвърждаване на речников запас и понятия, особено за профили с ограничена работна памет.", rgpd_note: "Quizlet Inc. (САЩ): данните за използване се споделят с трети страни за рекламни цели в безплатната версия. За ученици под 13 години е необходим акаунт, създаден от учителя (Quizlet Teacher). Версията Plus или School премахва рекламите и укрепва поверителността." },
    'speechify': { desc: "Висококачествен конвертор на текст в реч с естествени гласове на множество езици. Чете PDF файлове, уебстраници, документи и имейли. Позволява регулиране на скоростта на четене и подчертава текста при четене. Полезен за ученици с дислексия или диспраксия.", rgpd_note: "Speechify Inc. (САЩ): изпратеното съдържание се обработва на техните сървъри. Безплатната версия има ограничение за минути слушане; Premium е платена. За документи с ученически данни използвайте само анонимни учебни текстове." },
  },

  lt: {
    'chatgpt': { desc: "Bendrosios paskirties kalbos modelis. Naudingas tekstams pritaikyti, diferencijuotiems pratimams generuoti, kontekstualizuotiems pavyzdžiams kurti ir paramos medžiagai rengti.", rgpd_note: "Nemokamoji versija gali naudoti pokalbius modeliui mokyti. Išjunkite skiltyje Nustatymai > Duomenų valdymas. Niekada nesiųskite mokinių vardų, diagnozių ar tapatybės duomenų. Institucijoms rekomenduojama rinktis „Teams\" arba „Enterprise\" planą su duomenų tvarkymo sutartimi." },
    'deepl': { desc: "Aukštos kokybės mašininis vertimas, ypač geras Europos kalboms. Kontekstualiai tikslesnis nei „Google\" vertėjas akademiniams tekstams.", rgpd_note: "Nemokamoji versija siunčia tekstą į išorinius serverius (DeepL GmbH, Vokietija, ES viduje). „Pro\" versija apima BDAR atitinkančią duomenų tvarkymo sutartį. Niekada neverskite dokumentų su pilnais vardais ar jautriaisiais mokinių duomenimis." },
    'diffit': { desc: "Generuoja diferencijuotą skaitymo medžiagą iš bet kokio teksto, URL ar temos. Automatiškai pritaiko kalbinį sudėtingumo lygį išlaikydamas akademinį turinį. Naudinga kuriant to paties teksto versijas skirtingiems mokinių profiliams.", rgpd_note: "Diffit (JAV): pateiktas turinys gali būti apdorojamas išoriniais DI modeliais. Neįveskite asmeninių mokinių duomenų; naudokite tik su anoniminiu ugdymo turiniu." },
    'elsa-speak': { desc: "DI grįstas anglų kalbos tarimo treneris. Analizuoja vartotojo kalbą ir pateikia grįžtamąjį ryšį fonemą po fonemos. Ypač naudingas mokiniams, besimokantiems anglų kaip antrosios kalbos, ir mokytojams, identifikuojantiems tarimo modelius, susijusius su mokinio gimtąja kalba.", rgpd_note: "ELSA Corp. (JAV): balso įrašai tvarkomi jų serveriuose. Nemokamoje versijoje funkcijos ribotos; „Pro\" yra mokama. Nepilnamečiams patikrinkite privatumo politiką ir gaukite tėvų sutikimą prieš naudodami balso duomenis." },
    'grammarly': { desc: "DI rašymo asistentas, taisantis gramatiką, rašybą ir skyrybą bei siūlantis aiškumo ir tono patobulinimus. Pasiekiamas kaip naršyklės plėtinys ir integruotas į „Google Docs\" ir „Word\".", rgpd_note: "Grammarly Inc. (JAV): duomenys siunčiami į JAV serverius. Nemokamoji versija gali naudoti tekstus modeliui tobulinti. Nesiunčiant jautraus mokinių turinio nenaudokite tapatybę atskleidžiančių duomenų tekstų. „Business\" versijoje yra papildomų privatumo valdiklių." },
    'immersive-reader': { desc: "Nemokamas panardintis skaitytuvas, integruotas į „Word\", „Teams\", „OneNote\" ir „Edge\". Skaido žodžius į skiemenis, paryškina kalbos dalis, skaito tekstą garsiai bei reguliuoja tarpus ir šrifto dydį. Veikia tiesiogiai klasės dokumentuose.", rgpd_note: "Integruotas į „Microsoft\" produktus: duomenų tvarkymas atitinka „Microsoft 365\" privatumo politiką. Mokyklų aplinkoje su „Microsoft 365 Education\" licencija mokinių duomenys tvarkomi kaip mokyklos duomenys ir nenaudojami reklamai." },
    'khanmigo': { desc: "Nemokama mokymosi platforma su DI kuratoriumi (Khanmigo). DI kuratorius pritaiko paaiškinimus prie mokinio tempo, užduoda sokratinius klausimus vietoj tiesioginių atsakymų ir stebi pažangą. Ypač naudingas gabiems mokiniams ir lietuvių kalbą kaip antrąją besimokančiems.", rgpd_note: "Khan Academy (JAV, ne pelno siekianti): nepilnamečių mokinių duomenims reikalinga mokytojo ar globėjo sukurta paskyra. Khan Academy neparduoda duomenų reklamai. Khanmigo mokytojams kainuoja papildomai; bazinė platforma nemokama. Patikrinkite BDAR atitikimą naudojant ES viduje." },
    'magicschool': { desc: "DI platforma, sukurta specialiai mokytojams. Apima priemones pamokų planams diferencijuoti, pritaikymams mokiniams su specialiaisiais ugdymosi poreikiais kurti, komunikacijoms tėvams generuoti ir medžiagai prie skirtingų skaitymo lygių pritaikyti.", rgpd_note: "MagicSchool AI (JAV): platforma skirta ugdymo kontekstui, atitinkanti COPPA/FERPA JAV mokykloms. ES naudojimui patikrinkite BDAR atitikimą prieš įvesdami mokinių duomenis. Naudokite tik anoniminius ar fiktyvius duomenis, kol nebus patvirtinta duomenų tvarkymo sutartis su mokykla." },
    'natural-reader': { desc: "Konvertuoja rašytinį tekstą į sintetizuotą kalbą. Naudingas mokiniams, turintiems disleksijos ar dispraksijos, kuriems padeda garsinė pagalba skaitant.", rgpd_note: "Nemokamoji versija yra žiniatinklio pagrindu. Nesiųskite tekstų su asmeniškai identifikuojamais mokinių duomenimis." },
    'notebooklm': { desc: "Google priemonė, apdorojanti dokumentus ir leidžianti užduoti klausimus, generuoti santraukas ir kurti mokymosi vadovus iš įkeltos medžiagos. Naudinga ilgų tekstų pritaikymui.", rgpd_note: "Google produktas. Duomenys tvarkomi pagal „Google Workspace\" sąlygas. Nekelkite dokumentų su asmeniniais mokinių duomenimis. Naudokite tik su anoniminiu ugdymo turiniu." },
    'otter': { desc: "Automatinis garso transkripcija realiuoju laiku. Naudingas mokiniams, turintiems ADHD ar klausos apdorojimo sunkumų, žodiniams paaiškinimams sekti, ir mokytojams, kuriantiems pamokų transkripcijas peržiūrai.", rgpd_note: "Otter.ai (JAV): garso įrašai ir transkripcijos saugomi jų serveriuose. Prieš įrašant bet kurią pamoką gaukite informuotą sutikimą. Nemokamoji versija saugo įrašus neribotą laiką; patvirtinkite saugojimo politiką. Neįrašykite pokalbių su nepilnamečiais be aiškaus leidimo." },
    'quizlet': { desc: "Kortelių mokymosi ir edukacinių žaidimų platforma. DI funkcija automatiškai generuoja mokymosi rinkinius iš užrašų ar dokumentų. Veiksminga žodyno ir sąvokų įtvirtinimui, ypač profiliams su ribota darbine atmintimi.", rgpd_note: "Quizlet Inc. (JAV): naudojimo duomenys nemokamojoje versijoje dalijami su trečiosiomis šalimis reklamos tikslais. Mokiniams iki 13 metų reikalinga mokytojo sukurta paskyra (Quizlet Teacher). „Plus\" ar „School\" versija pašalina reklamas ir stiprina privatumą." },
    'speechify': { desc: "Aukštos kokybės teksto-į-kalbą keitiklis su natūraliais balsais keliomis kalbomis. Skaito PDF failus, tinklalapius, dokumentus ir el. laiškus. Leidžia reguliuoti skaitymo greitį ir paryškina tekstą skaitant. Naudingas mokiniams, turintiems disleksijos ar dispraksijos.", rgpd_note: "Speechify Inc. (JAV): pateiktas turinys apdorojamas jų serveriuose. Nemokamoji versija turi klausymosi minučių limitą; „Premium\" yra mokama. Dokumentams su mokinių duomenimis naudokite tik anoniminius ugdymo tekstus." },
  },

  lv: {
    'chatgpt': { desc: "Vispārējas nozīmes valodas modelis. Noderīgs tekstu pielāgošanai, diferencētu uzdevumu ģenerēšanai, kontekstualizētu piemēru veidošanai un atbalsta materiālu sagatavošanai.", rgpd_note: "Bezmaksas versija var izmantot sarunas modeļa apmācībai. Atspējojiet sadaļā Iestatījumi > Datu pārvaldība. Nekad nesūtiet skolēnu vārdus, diagnozes vai identificējošus datus. Institucionālai lietošanai apsveriet Teams vai Enterprise plānu ar datu apstrādes līgumu." },
    'deepl': { desc: "Augstas kvalitātes mašīntulkošana ar izciliem rezultātiem Eiropas valodās. Kontekstuāli precīzāks par Google Translate akadēmiskiem tekstiem.", rgpd_note: "Bezmaksas versija nosūta tekstu uz ārējiem serveriem (DeepL GmbH, Vācija, ES iekšienē). Pro versija ietver VDAR atbilstošu datu apstrādes līgumu. Nekad netulkojiet dokumentus ar pilniem vārdiem vai sensitīviem skolēnu datiem." },
    'diffit': { desc: "Ģenerē diferencētus lasīšanas materiālus no jebkura teksta, URL vai tēmas. Automātiski pielāgo valodas sarežģītības līmeni, saglabājot akadēmisko saturu. Noderīgi veidojot viena teksta versijas dažādiem skolēnu profiliem.", rgpd_note: "Diffit (ASV): iesniegtais saturs var tikt apstrādāts ar ārējiem MI modeļiem. Neievadiet personiskus skolēnu datus; izmantojiet tikai ar anonīmu mācību saturu." },
    'elsa-speak': { desc: "MI balstīts angļu valodas izrunas treneris. Analizē lietotāja runu un sniedz atgriezenisko saiti fonēmu pa fonēmam. Īpaši noderīgs skolēniem, kuri apgūst angļu kā otro valodu, un skolotājiem, kas identificē izrunas modeļus saistītu ar skolēna dzimto valodu.", rgpd_note: "ELSA Corp. (ASV): balss ieraksti tiek apstrādāti viņu serveros. Bezmaksas versijai ir ierobežotas funkcijas; Pro ir maksas. Nepilngadīgajiem pārbaudiet konfidencialitātes politiku un iegūstiet vecāku piekrišanu pirms balss datu izmantošanas." },
    'grammarly': { desc: "MI rakstīšanas asistents, kas labo gramatiku, pareizrakstību un interpunkciju un iesaka skaidrības un toņa uzlabojumus. Pieejams kā pārlūkprogrammas paplašinājums un integrēts Google Docs un Word.", rgpd_note: "Grammarly Inc. (ASV): dati tiek nosūtīti uz ASV serveriem. Bezmaksas versija var izmantot tekstus modeļa uzlabošanai. Sensitīvam skolēnu saturam neizmantojiet tekstus ar identificējošiem datiem. Business versija ietver papildu konfidencialitātes vadīklas." },
    'immersive-reader': { desc: "Bezmaksas imersīvais lasītājs, integrēts Word, Teams, OneNote un Edge. Sadala vārdus zilbēs, izceļ vārdšķiras, lasa tekstu skaļi un pielāgo atstarpes un fontu izmēru. Darbojas tieši klases dokumentos.", rgpd_note: "Integrēts Microsoft produktos: datu apstrāde atbilst Microsoft 365 konfidencialitātes politikai. Skolas vidē ar Microsoft 365 Education licenci skolēnu dati tiek apstrādāti kā skolas dati un netiek izmantoti reklāmai." },
    'khanmigo': { desc: "Bezmaksas mācību platforma ar MI mentoru (Khanmigo). MI mentors pielāgo skaidrojumus skolēna tempam, uzdod sokratiskus jautājumus nevis sniedz tiešas atbildes un seko progresam. Īpaši noderīgs apdāvinātiem skolēniem un tiem, kuri apgūst latviešu kā otro valodu.", rgpd_note: "Khan Academy (ASV, bezpeļņas): nepilngadīgo skolēnu datiem nepieciešams skolotāja vai aizbildņa izveidots konts. Khan Academy nepārdod datus reklāmai. Khanmigo skolotājiem ir papildu izmaksas; pamata platforma ir bezmaksas. Pārbaudiet VDAR atbilstību ES lietošanai." },
    'magicschool': { desc: "MI platforma, kas izstrādāta īpaši skolotājiem. Ietver rīkus stundu plānu diferenciācijai, pielāgojumu veidošanai skolēniem ar īpašām vajadzībām, saziņas ģenerēšanai vecākiem un materiālu pielāgošanai dažādiem lasīšanas līmeņiem.", rgpd_note: "MagicSchool AI (ASV): platforma izstrādāta izglītības kontekstam, COPPA/FERPA atbilstoša ASV skolām. ES lietošanai pārbaudiet VDAR atbilstību pirms skolēnu datu ievadīšanas. Izmantojiet tikai anonīmus vai fiktīvus datus, līdz ar skolu tiek apstiprināts datu apstrādes līgums." },
    'natural-reader': { desc: "Pārvērš rakstītu tekstu sintezētā runā. Noderīgs skolēniem ar disleksiju vai dispraksiju, kuri gūst labumu no dzirdes atbalsta lasīšanas laikā.", rgpd_note: "Bezmaksas versija ir tīmekļa bāzēta. Nesūtiet tekstus ar personiski identificējamiem skolēnu datiem." },
    'notebooklm': { desc: "Google rīks, kas apstrādā dokumentus un ļauj uzdot jautājumus, ģenerēt kopsavilkumus un veidot mācību ceļvežus no augšupielādētā materiāla. Noderīgs garu tekstu pielāgošanai.", rgpd_note: "Google produkts. Dati tiek apstrādāti saskaņā ar Google Workspace noteikumiem. Neaugšupielādējiet dokumentus ar personiskiem skolēnu datiem. Izmantojiet tikai ar anonīmu mācību materiālu." },
    'otter': { desc: "Automātiskā audio transkripcija reāllaikā. Noderīga skolēniem ar ADHD vai dzirdes apstrādes grūtībām mutiskiem skaidrojumiem sekot līdzi, un skolotājiem, kas veido stundu transkripcijas atkārtošanai.", rgpd_note: "Otter.ai (ASV): audio ieraksti un transkripcijas tiek glabātas viņu serveros. Pirms jebkuras stundas ierakstīšanas iegūstiet informētu piekrišanu. Bezmaksas versija glabā ierakstus uz nenoteiktu laiku; apstipriniet saglabāšanas politiku. Neierakstiet sarunas ar nepilngadīgajiem bez skaidras atļaujas." },
    'quizlet': { desc: "Zibatmiņu karšu un izglītojošo spēļu platforma. MI funkcija automātiski ģenerē mācīšanās komplektus no piezīmēm vai dokumentiem. Efektīva vārdu krājuma un jēdzienu nostiprināšanai, īpaši profiliem ar ierobežotu darba atmiņu.", rgpd_note: "Quizlet Inc. (ASV): lietošanas dati bezmaksas versijā tiek kopīgoti ar trešajām pusēm reklāmas nolūkos. Skolēniem līdz 13 gadiem nepieciešams skolotāja izveidots konts (Quizlet Teacher). Plus vai School versija noņem reklāmas un stiprina konfidencialitāti." },
    'speechify': { desc: "Augstas kvalitātes teksta pārvēršana runā ar dabiskiem balsīm vairākās valodās. Lasa PDF failus, tīmekļa lapas, dokumentus un e-pastus. Ļauj regulēt lasīšanas ātrumu un iezīmē tekstu lasīšanas laikā. Noderīgs skolēniem ar disleksiju vai dispraksiju.", rgpd_note: "Speechify Inc. (ASV): iesniegtais saturs tiek apstrādāts viņu serveros. Bezmaksas versijai ir klausīšanās minūšu limits; Premium ir maksas. Dokumentiem ar skolēnu datiem izmantojiet tikai anonīmus mācību tekstus." },
  },

  et: {
    'chatgpt': { desc: "Üldotstarbeline keelemuudel. Kasulik tekstide kohandamiseks, diferentseeritud harjutuste loomiseks, kontekstualiseeritud näidete arendamiseks ja toetusmaterjali koostamiseks.", rgpd_note: "Tasuta versioon võib kasutada vestlusi mudeli treenimiseks. Keelake seadetes Andmehaldus. Ärge kunagi saatke õpilaste nimesid, diagnoose ega identifitseerivaid andmeid. Institutsionaalseks kasutuseks kaaluge Teams- või Enterprise-plaani andmetöötluslepinguga." },
    'deepl': { desc: "Kõrgekvaliteediline masintõlge suurepäraste tulemustega Euroopa keeltes. Kontekstuaalselt täpsem kui Google Translate akadeemiliste tekstide puhul.", rgpd_note: "Tasuta versioon saadab teksti välistele serveritele (DeepL GmbH, Saksamaa, EL-is). Pro versioon sisaldab GDPR-ühilduvat andmetöötluslepingut. Ärge kunagi tõlkige dokumente täisnimede või tundlike õpilaste andmetega." },
    'diffit': { desc: "Loob diferentseeritud lugemismaterjale mis tahes tekstist, URL-ist või teemast. Kohandab automaatselt keelelist keerukustaset, säilitades akadeemilise sisu. Kasulik sama teksti erinevate versioonide loomiseks eri õpilasprofiilide jaoks.", rgpd_note: "Diffit (USA): esitatud sisu võivad töödelda välised tehisintellekti mudelid. Ärge sisestage õpilaste isikuandmeid; kasutage ainult anonüümse õppekavamaterjaliga." },
    'elsa-speak': { desc: "Tehisintellektipõhine inglise keele häälduse treener. Analüüsib kasutaja kõnet ja annab tagasisidet foneemi kaupa. Eriti kasulik inglise keelt teise keelena õppivatele õpilastele ja õpetajatele, kes tuvastavad hääldusmustreid seoses õpilase emakeelega.", rgpd_note: "ELSA Corp. (USA): häälsalvestused töödeldakse nende serverites. Tasuta versioonil on piiratud funktsioonid; Pro on tasuline. Alaealiste puhul kontrollige privaatsuspoliitikat ja hankige vanema nõusolek enne häälsalvestuste kasutamist." },
    'grammarly': { desc: "Tehisintellekti kirjutamisassistent, mis parandab grammatikat, õigekirja ja kirjavahemärke ning soovitab selguse ja tooni parandusi. Saadaval brauserilaiendina ja integreeritud Google Docsi ja Wordi.", rgpd_note: "Grammarly Inc. (USA): andmed saadetakse USA serveritesse. Tasuta versioon võib kasutada tekste mudeli parendamiseks. Ärge kasutage identifitseerivaid andmeid sisaldavaid tekste tundliku õpilaste sisu jaoks. Business versioon sisaldab lisaandmekaitsereguleerimisi." },
    'immersive-reader': { desc: "Tasuta immersiivsed luger, mis on integreeritud Wordi, Teamsi, OneNote'i ja Edge'i. Jagab sõnad silpideks, tõstab esile sõnaliigid, loeb teksti valjusti ette ja kohandab vahet ning fondisuurust. Töötab otse klassiruumidokumentides.", rgpd_note: "Integreeritud Microsofti toodetesse: andmetöötlus järgib Microsoft 365 privaatsuspoliitikat. Koolide keskkondades Microsoft 365 Education litsentsiga käsitletakse õpilaste andmeid kooliandmetena ega kasutata reklaamimiseks." },
    'khanmigo': { desc: "Tasuta õppeplatvorm tehisintellekti juhendajaga (Khanmigo). Tehisintellekti juhendaja kohandab selgitused õpilase tempole, esitab sokraatilisi küsimusi otseste vastuste asemel ja jälgib edusamme. Eriti kasulik andekate õpilaste ja eesti keelt teise keelena õppivate jaoks.", rgpd_note: "Khan Academy (USA, mittetulunduslik): alaealiste õpilaste andmed nõuavad õpetaja või eestkostja loodud kontot. Khan Academy ei müü andmeid reklaamimiseks. Khanmigo on õpetajate jaoks lisatasus; baasiplatvorm on tasuta. Kontrollige GDPR-vastavust EL-i kasutuseks." },
    'magicschool': { desc: "Tehisintellektiplatvorm, mis on loodud spetsiaalselt õpetajatele. Sisaldab tööriistu tunniplaanide diferentseerimiseks, kohanduste loomiseks hariduslike erivajadustega õpilastele, vanemate kommunikatsioonide genereerimiseks ja materjalide kohandamiseks erinevatele lugemistasemetele.", rgpd_note: "MagicSchool AI (USA): haridusliku konteksti jaoks loodud platvorm, COPPA/FERPA-ühilduv USA koolidele. EL-i kasutuseks kontrollige GDPR-vastavust enne õpilaste andmete sisestamist. Kasutage ainult anonüümseid või fiktiivseid andmeid kuni kooli andmetöötluslepingu kinnitamiseni." },
    'natural-reader': { desc: "Teisendab kirjutatud teksti sünteesitud kõneks. Kasulik düsleksia või düspraksiga õpilastele, kes saavad kasu auditoorsest toetusest lugemise ajal.", rgpd_note: "Tasuta versioon on veebipõhine. Ärge saatke isiklikult tuvastatavaid õpilaste andmeid sisaldavaid tekste." },
    'notebooklm': { desc: "Google'i tööriist, mis töötleb dokumente ja võimaldab küsimuste esitamist, kokkuvõtete genereerimist ning üleslaaditud materjalist õpijuhendite loomist. Kasulik pikkade tekstide kohandamiseks.", rgpd_note: "Google'i toode. Andmeid töödeldakse vastavalt Google Workspace'i tingimustele. Ärge laadige üles õpilaste isikuandmeid sisaldavaid dokumente. Kasutage ainult anonüümse õppematerjaliga." },
    'otter': { desc: "Automaatne helitranskriptsioon reaalajas. Kasulik ADHD-ga või kuuldelise töötluse raskustega õpilastele suuliste selgituste jälgimiseks ning õpetajatele, kes loovad kordamiseks tunnitranskriptsioone.", rgpd_note: "Otter.ai (USA): helisalvestused ja transkriptsioonid salvestatakse nende serveritesse. Enne tunnisalvestamist hankige teadlik nõusolek. Tasuta versioon hoiab salvestusi tähtajatult; kinnitage säilituspoliitika. Ärge salvestage alaealiste vestlusi ilma selge loata." },
    'quizlet': { desc: "Märgistuskaartide ja õppemängude platvorm. Tehisintellekti funktsioon genereerib automaatselt õppekomplekte märkmetest või dokumentidest. Tõhus sõnavara ja mõistete kinnistamiseks, eriti piiratud töömäluga profiilide puhul.", rgpd_note: "Quizlet Inc. (USA): tasuta versioonis jagatakse kasutusandmeid kolmandate osapooltega reklaami eesmärgil. Alla 13-aastaste õpilaste puhul on vajalik õpetaja loodud konto (Quizlet Teacher). Plus- või School-versioon eemaldab reklaamid ja tugevdab privaatsust." },
    'speechify': { desc: "Kõrgekvaliteediline tekst-kõneks konverter loomuliku kõlaga mitmetes keeltes. Loeb ette PDF-faile, veebilehti, dokumente ja e-kirju. Võimaldab lugemiskiiruse kohandamist ja tõstab lugemise ajal teksti esile. Kasulik düsleksia või düspraksiga õpilastele.", rgpd_note: "Speechify Inc. (USA): esitatud sisu töödeldakse nende serverites. Tasuta versioonil on kuulamisminutite limiit; Premium on tasuline. Õpilaste andmeid sisaldavatele dokumentidele kasutage ainult anonüümseid õppetekste." },
  },

  sl: {
    'chatgpt': { desc: "Splošno namenski jezikovni model. Koristen za prilagajanje besedil, ustvarjanje diferenciranih vaj, razvijanje kontekstualiziranih primerov in pripravo gradiv za podporo.", rgpd_note: "Brezplačna različica lahko pogovore uporablja za usposabljanje modela. Izklopite v Nastavitve > Upravljanje podatkov. Nikoli ne pošiljajte imen, diagnoz ali osebnih podatkov učencev. Za institucijsko rabo razmislite o načrtu Teams ali Enterprise s pogodbo o obdelavi podatkov." },
    'deepl': { desc: "Visokokakovostno strojno prevajanje z odličnimi rezultati za evropske jezike. Kontekstualno natančnejše od Google Prevajalnika za akademska besedila.", rgpd_note: "Brezplačna različica pošilja besedilo na zunanje strežnike (DeepL GmbH, Nemčija, znotraj EU). Različica Pro vključuje pogodbo o obdelavi podatkov, skladno z GDPR. Nikoli ne prevajajte dokumentov s polnimi imeni ali občutljivimi podatki učencev." },
    'diffit': { desc: "Ustvari diferencirano bralno gradivo iz katerega koli besedila, URL-ja ali teme. Samodejno prilagaja raven jezikovne zahtevnosti ob ohranitvi akademske vsebine. Koristno za ustvarjanje različnih različic istega besedila za različne profile učencev.", rgpd_note: "Diffit (ZDA): oddano vsebino lahko obdelajo zunanji modeli umetne inteligence. Ne vnašajte osebnih podatkov učencev; uporabljajte samo z anonimno učno vsebino." },
    'elsa-speak': { desc: "Trener izgovorjave angleščine z umetno inteligenco. Analizira govor uporabnika in podaja povratne informacije fonem za fonemom. Posebej koristno za učence, ki se učijo angleščine kot J2, in za učitelje, ki prepoznavajo vzorce izgovorjave, povezane z maternim jezikom učenca.", rgpd_note: "ELSA Corp. (ZDA): glasovni posnetki se obdelujejo na njihovih strežnikih. Brezplačna različica ima omejene funkcije; Pro je plačljiva. Za mladoletne preverite pravilnik o zasebnosti in pridobite starševsko soglasje pred uporabo glasovnih podatkov." },
    'grammarly': { desc: "Pomočnik pri pisanju z umetno inteligenco, ki popravlja slovnico, pravopis in ločila ter predlaga izboljšave jasnosti in tona. Na voljo kot razširitev brskalnika in integriran v Google Docs in Word.", rgpd_note: "Grammarly Inc. (ZDA): podatki se pošiljajo na ameriške strežnike. Brezplačna različica lahko besedila uporablja za izboljšanje modela. Za občutljivo vsebino učencev ne uporabljajte besedil z osebnimi podatki. Različica Business vključuje dodatne nadzore zasebnosti." },
    'immersive-reader': { desc: "Brezplačni imerzivni bralnik, integriran v Word, Teams, OneNote in Edge. Deli besede na zloge, poudarja besedne vrste, bere besedilo na glas in prilagaja presledke ter velikost pisave. Deluje neposredno v razrednih dokumentih.", rgpd_note: "Integriran v Microsoftove produkte: obdelava podatkov sledi pravilniku o zasebnosti Microsoft 365. V šolskih okoljih z licenco Microsoft 365 Education se podatki učencev obravnavajo kot šolski podatki in se ne uporabljajo za oglaševanje." },
    'khanmigo': { desc: "Brezplačna učna platforma z mentorjem umetne inteligence (Khanmigo). Mentor UI prilagaja razlage tempu učenca, postavlja sokratska vprašanja namesto neposrednih odgovorov in spremlja napredek. Posebej koristno za nadarjene učence in tiste, ki se učijo slovenščine kot J2.", rgpd_note: "Khan Academy (ZDA, neprofitna): podatki mladoletnih učencev zahtevajo račun, ki ga ustvari učitelj ali skrbnik. Khan Academy ne prodaja podatkov za oglaševanje. Khanmigo ima za učitelje doplačilo; osnovna platforma je brezplačna. Preverite skladnost z GDPR za uporabo v EU." },
    'magicschool': { desc: "Platforma UI, zasnovana posebej za učitelje. Vključuje orodja za diferenciacijo učnih načrtov, ustvarjanje prilagoditev za učence s posebnimi potrebami, generiranje komunikacij za starše in prilagajanje gradiv različnim ravnem branja.", rgpd_note: "MagicSchool AI (ZDA): platforma zasnovana za izobraževalni kontekst, skladna s COPPA/FERPA za ameriške šole. Za uporabo v EU preverite skladnost z GDPR pred vnosom podatkov učencev. Uporabljajte samo anonimne ali izmišljene podatke, dokler ni potrjena pogodba o obdelavi podatkov s šolo." },
    'natural-reader': { desc: "Pretvori pisano besedilo v sintetiziran govor. Koristno za učence z disleksijo ali dispraksijo, ki jim koristi zvočna podpora med branjem.", rgpd_note: "Brezplačna različica je spletna. Ne pošiljajte besedil z osebno določljivimi podatki učencev." },
    'notebooklm': { desc: "Googlovo orodje, ki obdeluje dokumente in omogoča postavljanje vprašanj, generiranje povzetkov in ustvarjanje učnih vodičev iz naloženega gradiva. Koristno za prilagajanje dolgih besedil.", rgpd_note: "Googlov produkt. Podatki se obdelujejo v skladu s pogoji Google Workspace. Ne nalagajte dokumentov z osebnimi podatki učencev. Uporabljajte samo z anonimnim učnim gradivom." },
    'otter': { desc: "Samodejno zvočno prepisovanje v realnem času. Koristno za učence z ADHD ali težavami pri slušni predelavi za sledenje ustnim razlagam in za učitelje, ki ustvarjajo prepise ur za ponavljanje.", rgpd_note: "Otter.ai (ZDA): zvočni posnetki in prepisi so shranjeni na njihovih strežnikih. Pred snemanjem katere koli ure pridobite informirano soglasje. Brezplačna različica hrani posnetke za nedoločen čas; potrdite pravilnik o hrambi. Ne snemate pogovorov z mladoletnimi brez izrecnega dovoljenja." },
    'quizlet': { desc: "Platforma za kartice z besedami in izobraževalne igre. Funkcija UI samodejno ustvari učne sklope iz zapiskov ali dokumentov. Učinkovita za utrjevanje besedišča in pojmov, zlasti za profile z omejenim delovnim spominom.", rgpd_note: "Quizlet Inc. (ZDA): podatki o uporabi se v brezplačni različici delijo s tretjimi stranmi za oglaševalske namene. Za učence, mlajše od 13 let, je potreben račun, ki ga ustvari učitelj (Quizlet Teacher). Različica Plus ali School odstrani oglase in okrepí zasebnost." },
    'speechify': { desc: "Visokokakovostni pretvornik besedila v govor z naravnimi glasovi v več jezikih. Bere datoteke PDF, spletne strani, dokumente in e-pošto. Omogoča prilagajanje hitrosti branja in poudarja besedilo med branjem. Koristno za učence z disleksijo ali dispraksijo.", rgpd_note: "Speechify Inc. (ZDA): oddana vsebina se obdeluje na njihovih strežnikih. Brezplačna različica ima omejitev minut poslušanja; Premium je plačljiva. Za dokumente s podatki učencev uporabljajte samo anonimna učna besedila." },
  },

  ga: {
    'chatgpt': { desc: "Múnla teanga ilchuspóireach. Úsáideach chun téacsanna a oiriúnú, cleachtaí difreáilte a ghiniúint, samplaí comhthéacsúla a chruthú agus ábhair tacaíochta a dhréachtú.", rgpd_note: "Féadfaidh an leagan saor in aisce comhráite a úsáid chun an múnla a oiliúint. Múch i Socruithe > Rialuithe Sonraí. Ná seol ainmneacha, diagnóisí ná sonraí aitheantas daltaí go deo. Le haghaidh úsáide institiúidí, smaoinigh ar an bplean Teams nó Enterprise le Comhaontú Próiseála Sonraí." },
    'deepl': { desc: "Aistriúchán uathoibríoch ardchaighdeáin le torthaí den scoth do theangacha Eorpacha. Níos cruinne ó thaobh comhthéacs de ná Google Translate do théacsanna acadúla.", rgpd_note: "Seolann an leagan saor in aisce téacs chuig freastalaithe seachtracha (DeepL GmbH, an Ghearmáin, laistigh den AE). Áirítear sa leagan Pro conradh próiseála sonraí comhoiriúnach le GDPR. Ná haistrigh doiciméid le hainmneacha iomlána nó sonraí íogaire daltaí go deo." },
    'diffit': { desc: "Gineann ábhair léitheoireachta difreáilte ó aon téacs, URL nó ábhar. Oiriúnaíonn sé an leibhéal castachta teanga go huathoibríoch agus an t-inneachar acadúil á choimeád. Úsáideach chun leaganacha den téacs céanna a chruthú do phróifílí éagsúla daltaí.", rgpd_note: "Diffit (SAM): d'fhéadfadh múnlaí AI seachtracha an t-inneachar a sheolann tú a phróiseáil. Ná cuir isteach sonraí pearsanta daltaí; úsáid le hábhar curaclam anaithnid amháin." },
    'elsa-speak': { desc: "Traenálaí fuaimnithe Béarla le AI. Anailísíonn sé caint an úsáideora agus tugann sé aiseolas foném ar fhoném. Thar a bheith úsáideach do dhaoine a fhoghlaimíonn an Béarla mar T2 agus do mhúinteoirí a aithníonn patrúin fuaimnithe a bhaineann le céadteanga an dalta.", rgpd_note: "ELSA Corp. (SAM): próiseáiltear taifeadtaí gutha ar a bhfreastalaithe siúd. Tá gnéithe teoranta ag an leagan saor in aisce; tá Pro íoctha. I gcás mionaoiseach, seiceáil an polasaí príobháideachais agus faigh toiliú tuismitheoirí roimh shonraí gutha a úsáid." },
    'grammarly': { desc: "Cúntóir scríbhneoireachta AI a cheartaíonn gramadach, litriú agus poncaíocht agus a mholann feabhsuithe ar shoiléireacht agus ar thón. Ar fáil mar síneadh brabhsálaí agus comhtháite i Google Docs agus Word.", rgpd_note: "Grammarly Inc. (SAM): seoltar sonraí chuig freastalaithe Mheiriceá. Féadfaidh an leagan saor in aisce téacsanna a úsáid chun an múnla a fheabhsú. Ná húsáid téacsanna le sonraí aitheantais i gcás inneachair íogaigh daltaí. Áirítear rialuithe príobháideachais breise sa leagan Business." },
    'immersive-reader': { desc: "Léitheoir tumthach saor in aisce atá comhtháite in Word, Teams, OneNote agus Edge. Roinneann sé focail ina siollaí, aibhsíonn sé codanna cainte, léann sé téacs os ard agus coigeartaíonn sé spásáil agus méid cló. Oibríonn sé go díreach i ndoiciméid an ranga.", rgpd_note: "Comhtháite i dtáirgí Microsoft: leanann próiseáil sonraí polasaí príobháideachais Microsoft 365. I dtimpeallachtaí scoile le ceadúnas Microsoft 365 Education, déantar sonraí daltaí a chaitheamh mar shonraí scoile agus ní úsáidtear iad le haghaidh fógraíochta." },
    'khanmigo': { desc: "Ardán foghlama saor in aisce le meantóir AI (Khanmigo). Oiriúnaíonn an meantóir AI mínithe do luas an dalta, cuireann sé ceisteanna Sócratacha in ionad freagraí díreacha, agus rianaíonn sé dul chun cinn. Thar a bheith úsáideach do dhaltaí ard-inniúla agus do dhaltaí a fhoghlaimíonn an Ghaeilge mar T2.", rgpd_note: "Khan Academy (SAM, neamhbhrabúis): teastaíonn cuntas arna chruthú ag múinteoir nó caomhnóir do shonraí mionaoiseach daltaí. Ní dhíolann Khan Academy sonraí le haghaidh fógraíochta. Tá costas breise ar Khanmigo do mhúinteoirí; tá an t-ardán bonn saor in aisce. Seiceáil comhlíonadh GDPR le haghaidh úsáide san AE." },
    'magicschool': { desc: "Ardán AI atá deartha go sonrach do mhúinteoirí. Áirítear uirlisí chun pleananna ceachta a dhifreáil, cóiríochtaí a chruthú do dhaltaí le riachtanais speisialta oideachais, cumarsáid le tuismitheoirí a ghiniúint agus ábhair a oiriúnú do leibhéil léitheoireachta éagsúla.", rgpd_note: "MagicSchool AI (SAM): ardán deartha do chomhthéacs oideachais, comhoiriúnach le COPPA/FERPA do scoileanna Mheiriceá. Le haghaidh úsáide san AE, seiceáil comhlíonadh GDPR roimh shonraí daltaí a chur isteach. Úsáid sonraí anaithnide nó ficseanúla amháin go dtí go gcomhaontaítear an conradh próiseála sonraí leis an scoil." },
    'natural-reader': { desc: "Tiontaíonn téacs scríofa go caint shintéiseach. Úsáideach do dhaltaí le disléicse nó dioscaraicse a bhaineann tairbhe as tacaíocht éisteachta le linn léitheoireachta.", rgpd_note: "Tá an leagan saor in aisce gréasánbhunaithe. Ná seol téacsanna le sonraí daltaí aitheanta go pearsanta." },
    'notebooklm': { desc: "Uirlis Google a dhéanann doiciméid a phróiseáil agus a ligeann duit ceisteanna a chur, achoimrí a ghiniúint agus treoir staidéir a chruthú ón ábhar a uaslódáladh. Úsáideach chun téacsanna fada a oiriúnú.", rgpd_note: "Táirge Google. Próiseáiltear sonraí de réir théarmaí Google Workspace. Ná huaslódáil doiciméid le sonraí pearsanta daltaí. Úsáid le hábhar curaclam anaithnid amháin." },
    'otter': { desc: "Traschríobh uathoibríoch fuaime i bhfíor-am. Úsáideach do dhaltaí le ADHD nó deacrachtaí próiseála éisteachta chun mínithe béil a leanúint, agus do mhúinteoirí a chruthaíonn traschríobha ceachta le haghaidh athbhreithnithe.", rgpd_note: "Otter.ai (SAM): stóráiltear taifeadtaí fuaime agus traschríobha ar a bhfreastalaithe. Faigh toiliú feasach sula dtaifeadtar aon cheacht. Stórálann an leagan saor in aisce taifeadtaí go ceann achair éiginnte; deimhnigh an polasaí coinneála. Ná taifeadtar comhráite le mionaoiseach gan údarú sainráite." },
    'quizlet': { desc: "Ardán cártaí staidéir agus cluichí foghlama. Gineann an ghné AI sraitheanna staidéir go huathoibríoch ó nótaí nó doiciméid. Éifeachtach chun stór focal agus coincheapa a chomhdhlúthú, go háirithe do phróifílí le cuimhne oibre teoranta.", rgpd_note: "Quizlet Inc. (SAM): roinntear sonraí úsáide le tríú páirtithe chun críocha fógraíochta sa leagan saor in aisce. I gcás daltaí faoi bhun 13 bliana d'aois, teastaíonn cuntas arna chruthú ag múinteoir (Quizlet Teacher). Baineann an leagan Plus nó School fógraí agus neartaíonn sé príobháideachas." },
    'speechify': { desc: "Tiontaire ardchaighdeáin téacs-go-caint le guthanna nádúrtha i dteangacha iomadúla. Léann sé comhaid PDF, leathanaigh ghréasáin, doiciméid agus ríomhphost. Ligeann sé coigeartú luas léitheoireachta agus aibhsíonn sé téacs agus é á léamh. Úsáideach do dhaltaí le disléicse nó dioscaraicse.", rgpd_note: "Speechify Inc. (SAM): próiseáiltear an t-inneachar a sheoltar ar a bhfreastalaithe. Tá teorainn nóiméad éisteachta ar an leagan saor in aisce; tá Premium íoctha. I gcás doiciméad le sonraí daltaí, úsáid téacsanna curaclam anaithnide amháin." },
  },

  mt: {
    'chatgpt': { desc: "Mudell tal-lingwa għal użu ġenerali. Utli biex tadatta testi, tiġġenera eżerċizzji differenzjati, toħloq eżempji kkontestwalizzati u tiħħejji materjali ta' appoġġ.", rgpd_note: "Il-verżjoni b'xejn tista' tuża l-konversazzjonijiet biex tħarreġ il-mudell. Agħlaqha f'Impostazzjonijiet > Kontrolli tad-Dejta. Qatt m'għandek tibgħat ismijiet, dijanjożi jew dejta identifikabbli tal-istudenti. Għall-użu istituzzjonali, ikkunsidra l-pjan Teams jew Enterprise b'Ftehim dwar l-Ipproċessar tad-Dejta." },
    'deepl': { desc: "Traduzzjoni awtomatika ta' kwalità għolja b'riżultati eċċellenti għal-lingwi Ewropej. Aktar preċiż kontestwalment minn Google Translate għal testi akkademiċi.", rgpd_note: "Il-verżjoni b'xejn tibgħat test lil servers esterni (DeepL GmbH, il-Ġermanja, fl-UE). Il-verżjoni Pro tinkludi kuntratt tal-ipproċessar tad-dejta konformi mal-GDPR. Qatt m'għandek tittraduċi dokumenti b'ismijiet sħaħ jew dejta sensittiva tal-istudenti." },
    'diffit': { desc: "Jiġġenera materjali tal-qari differenzjati minn kwalunkwe test, URL jew suġġett. Jadatta awtomatikament il-livell tal-kumplessità lingwistika filwaqt li jżomm il-kontenut akkademiku. Utli biex toħloq verżjonijiet tal-istess test għal profili differenti tal-istudenti.", rgpd_note: "Diffit (USA): il-kontenut li tintbagħat jista' jiġi pproċessat minn mudelli AI esterni. Tiddaħħalx dejta personali tal-istudenti; uża biss ma' kontenut kurrikulari anonimu." },
    'elsa-speak': { desc: "Trainer tal-pronunzja tal-Ingliż b'AI. Janalizza l-kelma tal-utent u jagħti feedback fonem b'fonem. Partikolarment utli għal dawk li jitgħallmu l-Ingliż bħala L2 u għal għalliema li jidentifikaw mudelli tal-pronunzja marbuta mal-lingwa omm tal-istudent.", rgpd_note: "ELSA Corp. (USA): ir-reġistrazzjonijiet tal-vuċi jiġu pproċessati fuq is-servers tagħhom. Il-verżjoni b'xejn għandha funzjonalitajiet limitati; Pro hija mħallsa. Għal minuri, iċċekkja l-politika tal-privatezza u kseb il-kunsens tal-ġenituri qabel tuża dejta tal-vuċi." },
    'grammarly': { desc: "Assistent tal-kitba b'AI li jikkorriġi l-grammatika, l-ortografija u l-punteġġjatura u jissuġġerixxi titjib fil-ċarezza u t-ton. Disponibbli bħala estensjoni tal-browser u integrat f'Google Docs u Word.", rgpd_note: "Grammarly Inc. (USA): id-dejta tintbagħat lis-servers Amerikani. Il-verżjoni b'xejn tista' tuża testi biex ittejjeb il-mudell. Għal kontenut sensittiv tal-istudenti, tużax testi b'dejta identifikabbli. Il-verżjoni Business tinkludi kontrolli tal-privatezza addizzjonali." },
    'immersive-reader': { desc: "Qarrej immersiiv b'xejn integrat f'Word, Teams, OneNote u Edge. Jaqsam il-kliem f'sillabi, jenfasizza l-partijiet tad-diskors, jaqra t-test b'vuċi, u jaġġusta l-ispazjar u d-daqs tal-font. Jaħdem direttament fid-dokumenti tal-klassi.", rgpd_note: "Integrat fil-prodotti Microsoft: l-ipproċessar tad-dejta jsegwi l-politika tal-privatezza ta' Microsoft 365. Fl-ambjenti skolastiċi bil-liċenzja Microsoft 365 Education, id-dejta tal-istudenti tiġi trattata bħala dejta skolastika u ma tintumiex għar-reklamar." },
    'khanmigo': { desc: "Pjattaforma tat-tagħlim b'xejn b'tutur AI (Khanmigo). It-tutur AI jadatta l-ispjegazzjonijiet għar-ritmu tal-istudent, jagħmel mistoqsijiet Sokratiċi flok tweġibiet diretti, u jsegwi l-progress. Partikolarment utli għal studenti b'talenti partikolari u għal dawk li jitgħallmu l-Malti bħala L2.", rgpd_note: "Khan Academy (USA, mhux għall-qligħ): id-dejta tal-istudenti minorenni teħtieġ kont maħluq minn għalliem jew kuratur. Khan Academy ma tbigħx dejta għar-reklamar. Khanmigo għandu spiża addizzjonali għall-għalliema; il-pjattaforma bażi hija b'xejn. Iċċekkja l-konformità mal-GDPR għall-użu fl-UE." },
    'magicschool': { desc: "Pjattaforma AI mfassla speċifikament għall-għalliema. Tinkludi għodod biex tiddifferenzja l-pjanijiet tal-lezzjoni, toħloq akkomodazzjonijiet għall-istudenti b'bżonnijiet edukattivi speċjali, tiġġenera komunikazzjonijiet għall-ġenituri u tadatta l-materjali għal livelli differenti tal-qari.", rgpd_note: "MagicSchool AI (USA): pjattaforma mfassla għall-kuntest edukattiv, konformi mal-COPPA/FERPA għall-iskejjel Amerikani. Għall-użu fl-UE, iċċekkja l-konformità mal-GDPR qabel ddaħħal dejta tal-istudenti. Uża biss dejta anonima jew fittizja sakemm jiġi kkonfermat ftehim tal-ipproċessar tad-dejta mal-iskola." },
    'natural-reader': { desc: "Jikkonverti test miktub f'vuċi sintetizzata. Utli għal studenti bid-dislossija jew dispraxia li jibbenefikaw minn appoġġ awditorju waqt il-qari.", rgpd_note: "Il-verżjoni b'xejn hija bbażata fuq il-web. Tintbagħatx testi b'dejta personalment identifikabbli tal-istudenti." },
    'notebooklm': { desc: "Għodda Google li tidħol fid-dokumenti u tippermetti l-mistoqsijiet, il-ġenerazzjoni ta' sommarju u l-ħolqien ta' gwidi ta' studju mill-materjal li ġie mċarrat. Utli għall-adattament ta' testi twal.", rgpd_note: "Prodott Google. Id-dejta tiġi pproċessata skont it-termini ta' Google Workspace. Tittellax dokumenti b'dejta personali tal-istudenti. Uża biss ma' materjali kurrikulari anonimi." },
    'otter': { desc: "Traskrizzjoni awtomatika tal-awdjo f'ħin reali. Utli għal studenti b'ADHD jew diffikultajiet fil-pproċessar awditorju biex isegwu spjegazzjonijiet orali, u għal għalliema li joħolqu traskrizzjonijiet tal-lezzjonijiet biex jirrevedu.", rgpd_note: "Otter.ai (USA): ir-reġistrazzjonijiet tal-awdjo u t-traskrizzjonijiet jinħażnu fuq is-servers tagħhom. Ikseb kunsens informat qabel tirreġistra kwalunkwe lezzjoni. Il-verżjoni b'xejn taħżen ir-reġistrazzjonijiet għal żmien indefinit; ikkonferma l-politika taż-żamma. Tirreġistrax konversazzjonijiet ma' minorenni mingħajr awtorizzazzjoni espliċita." },
    'quizlet': { desc: "Pjattaforma ta' karti tal-istudju u logħob tat-tagħlim. Il-funzjoni AI tiġġenera awtomatikament settijiet ta' studju minn noti jew dokumenti. Effettiva għall-konsolidament tal-vokabolarju u l-kunċetti, speċjalment għal profili b'memorja tax-xogħol limitata.", rgpd_note: "Quizlet Inc. (USA): id-dejta tal-użu tinqasam ma' partijiet terzi għal skopijiet ta' reklamar fil-verżjoni b'xejn. Għal studenti taħt it-13-il sena, hija meħtieġa kont maħluq mill-għalliem (Quizlet Teacher). Il-verżjoni Plus jew School tneħħi r-reklami u ssaħħaħ il-privatezza." },
    'speechify': { desc: "Konvertitur test-għal-vuċi ta' kwalità għolja b'vuċi naturali f'ħafna lingwi. Jaqra fajls PDF, paġni web, dokumenti u emails. Jippermetti l-aġġustament tal-veloċità tal-qari u jenfasizza t-test hekk kif jinqara. Utli għal studenti bid-dislossija jew dispraxia.", rgpd_note: "Speechify Inc. (USA): il-kontenut li jintbagħat jiġi pproċessat fuq is-servers tagħhom. Il-verżjoni b'xejn għandha limitu ta' minuti tal-isma'; Premium hija mħallsa. Għal dokumenti b'dejta tal-istudenti, uża biss testi kurrikulari anonimi." },
  },

};
